Below is a concise explanation followed by complete MATLAB code.

How the modifications minimize the sum of squared two-norms (H2 objective)
- Goal: Minimize ||T_w→y||_2^2 + ||T_w→u||_2^2 by stacking z = [y; u] = [C x; −K x]. Then ||T_w→z||_2^2 equals the sum you want.
- Lyapunov variable: Choose X > 0 such that the closed-loop controllability Gramian satisfies (A − B K) X + X (A − B K)' + B B' < 0 when w enters through B. This guarantees internal stability and defines the H2 metric.
- Nonlinearity and change of variables: The bilinearity in K X is removed by the substitution Y = K X. The stability LMI becomes linear: A X + X A' − (B Y + Y' B') + B B' < 0.
- Schur complement (Schur lemma) for the H2 term: The squared H2 norm can be written as trace((C1 − D12 K) X (C1 − D12 K)') with C1 = [C; 0], D12 = [0; I]. Using Y = KX, define S = C1 X − D12 Y. The Schur complement enforces Z ≥ S X^{-1} S' via the LMI:
  [ Z, S; S', X ] >= 0
  Minimizing trace(Z) thus minimizes trace(S X^{-1} S') = trace((C1 − D12 K) X (C1 − D12 K)'), i.e., the squared H2 norm from w to z = [y; u]. This is exactly the sum of squared H2 norms from w to the plant output and to the control input.

Deeper H2 controller insight
- H2 performance is the L2 energy of z in response to a unit-energy white-noise w. With the chosen Lyapunov variable X (reachability Gramian), the H2 cost is linear in X once the dependence on K is handled, and the Schur complement removes the remaining X^{-1} nonlinearity.
- The resulting program is convex in (X, Y, Z), solved efficiently by LMI solvers, and yields the optimal state-feedback K = Y X^{-1}.

% H2 state-feedback via LMIs (Schur complement) with Y = KX
% + Step-response comparison vs LQR for y (output) and u (control input)

clc
clear
close all

% Load data and identify model
load('data3.mat');                      % expects variable 'data3'
G3  = bj(data3, [5 5 5 5 1]);           % Box-Jenkins identification (typical SISO)
G3c = d2c(G3);                          % Discrete -> continuous
sysc = ss(G3c);                         % Convert to state-space
[A,B,C,D] = ssdata(sysc);
n = size(A,1);
m = size(B,2);
p = size(C,1);

% Generalized plant for H2:
% xdot = A x + B (w + u),   u = -K x
% z    = [C x; -K x] = C1 x + D12 u, with Y = KX
C1  = [C; zeros(m,n)];                  % For z = [y; u] = C1 x + D12 u
D12 = [zeros(p,m); eye(m)];

% YALMIP decision variables
X = sdpvar(n,n,'symmetric');            % X > 0 (Lyapunov/controllability Gramian)
Y = sdpvar(m,n,'full');                 % Y = K X
Z = sdpvar(p+m,p+m,'symmetric');        % For H2 objective via Schur complement

% LMIs:
% 1) Closed-loop Lyapunov with disturbance at same input B:
%    (A - B K) X + X (A - B K)' + B B' < 0
%    -> A X + X A' - (B Y + Y' B') + B B' < 0  using Y = KX
eps_stab = 1e-9;
LMI_cl = A*X + X*A' - (B*Y + Y'*B') + (B*B') <= -eps_stab*eye(n);

% 2) H2 objective (z = C1 x + D12 u, u = -K x, Y = KX) via Schur complement:
%    Z >= (C1 X - D12 Y) X^{-1} (C1 X - D12 Y)'
%    <=> [ Z,  (C1 X - D12 Y)
%          *,               X ] >= 0
S = C1*X - D12*Y;
LMI_h2 = [ Z,  S ; S',  X ] >= 0;

% Positive definiteness
LMI_pos = X >= 1e-6*eye(n);

Constraints = [LMI_cl, LMI_h2, LMI_pos];

% Objective: minimize trace(Z) = ||T_{w->z}||_2^2 with z = [y; u]
Objective = trace(Z);

% Select solver (MOSEK preferred; fallback to SeDuMi)
if exist('mosekopt','file') == 3 || exist('mosekopt','file') == 2
    solver = 'mosek';
else
    solver = 'sedumi';
end
ops = sdpsettings('solver',solver,'verbose',1);

% Solve the SDP
sol = optimize(Constraints, Objective, ops);
assert(sol.problem == 0, ['SDP failed: ', sol.info]);

% Recover controller K and H2 norm
Xv = value(X);
Yv = value(Y);
K_H2 = Yv / Xv;                          % K = Y * X^{-1}
H2sq = value(trace(Z));                   % squared H2 norm from w to z = [y; u]
H2norm = sqrt(max(H2sq,0));

fprintf('H2 synthesis successful.\\n');
fprintf('||T_{w->[y;u]}||_2 = %.6f\\n', H2norm);

% Closed-loop systems (from disturbance w to outputs) for H2
Acl = A - B*K_H2;
Bcl = B;
sys_w2y_H2 = ss(Acl, Bcl, C, zeros(p,m));     % from w to y
sys_w2u_H2 = ss(Acl, Bcl, -K_H2, zeros(m,m)); % from w to u

% LQR comparison (standard full-state feedback)
Q = eye(n);
R = eye(m);                                   % allow multi-input plants
K_LQR = lqr(A,B,Q,R);

Acl_lqr = A - B*K_LQR;
sys_w2y_LQR = ss(Acl_lqr, Bcl, C, zeros(p,m));
sys_w2u_LQR = ss(Acl_lqr, Bcl, -K_LQR, zeros(m,m));

% Step response comparisons (disturbance step at input channel 'inp')
tFinal = 5;                                   % seconds; adjust as needed
t = linspace(0,tFinal,1000).';
inp = 1;                                      % compare first disturbance channel

% y response: from w(inp) to each output y(i)
[Y_H2, ty]  = step(sys_w2y_H2(:,inp), t);
[Y_LQR, ~]  = step(sys_w2y_LQR(:,inp), t);
if ndims(Y_H2) == 3, Y_H2 = squeeze(Y_H2); end
if ndims(Y_LQR) == 3, Y_LQR = squeeze(Y_LQR); end

for i = 1:p
    figure
    plot(ty, Y_H2(:,i), 'b-', 'LineWidth', 1.5); hold on
    plot(ty, Y_LQR(:,i), 'r--', 'LineWidth', 1.5); grid on
    xlabel('Time [s]'); ylabel(sprintf('y(%d)', i));
    title(sprintf('Step: w(%d) -> y(%d)', inp, i));
    legend('H2', 'LQR', 'Location', 'Best');
end

% u response: from w(inp) to each control input u(j)
[U_H2, tu]  = step(sys_w2u_H2(:,inp), t);
[U_LQR, ~]  = step(sys_w2u_LQR(:,inp), t);
if ndims(U_H2) == 3, U_H2 = squeeze(U_H2); end
if ndims(U_LQR) == 3, U_LQR = squeeze(U_LQR); end

for j = 1:m
    figure
    plot(tu, U_H2(:,j), 'b-', 'LineWidth', 1.5); hold on
    plot(tu, U_LQR(:,j), 'r--', 'LineWidth', 1.5); grid on
    xlabel('Time [s]'); ylabel(sprintf('u(%d)', j));
    title(sprintf('Step: w(%d) -> u(%d)', inp, j));
    legend('H2', 'LQR', 'Location', 'Best');
end

% Optional: closed-loop pole check
fprintf('Closed-loop poles (H2):\\n'); disp(eig(Acl).');
fprintf('Closed-loop poles (LQR):\\n'); disp(eig(Acl_lqr).');

Below is a complete, multi-page documentation management feature for a Next.js (App Router) app that uses Firebase (Firestore + Storage), Tailwind CSS, and a MarkdownRX engine (unified/remark/rehype) for rendering/preview. It includes:

- Multi-page system
  - /docs (list, search/filter, create new)
  - /docs/[slug] (single doc edit/preview, rename, delete)
- Firebase data model and live updates with Firestore
- Image uploads to Firebase Storage (integrated with the editor)
- A MarkdownRX-powered editor and preview
- Client-side components annotated with "use client"

Install dependencies:
- npm i firebase
- npm i unified remark-parse remark-gfm remark-slug remark-rehype rehype-autolink-headings rehype-highlight highlight.js rehype-stringify rehype-sanitize hast-util-sanitize
- Optional (nicer preview): npm i -D @tailwindcss/typography and enable the plugin; then use className="prose"

