# ============================================
# File: components/DocEditor.tsx
# High-level document editor integrated with Firebase (Firestore + Storage)
# - Loads/saves a doc by slug
# - Title, tags, markdown content
# - Auto-save and manual save
# - Image upload to Storage
# - Rename slug & Delete document
# ============================================
doc_editor_tsx = r'''
"use client";

import * as React from "react";
import { db, storage } from "@/lib/firebase";
import {
  doc,
  getDoc,
  onSnapshot,
  serverTimestamp,
  setDoc,
  updateDoc,
  deleteDoc,
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { MarkdownRXEditor, MarkdownRXPreview } from "@/components/MarkdownRX";
import { useRouter } from "next/navigation";

type DocData = {
  title: string;
  content: string;
  tags?: string[];
  createdAt?: any;
  updatedAt?: any;
};

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

export default function DocEditor({ slug }: { slug: string }) {
  const [docData, setDocData] = React.useState<DocData | null>(null);
  const [title, setTitle] = React.useState<string>("");
  const [tagsText, setTagsText] = React.useState<string>("");
  const [content, setContent] = React.useState<string>("");
  const [saving, setSaving] = React.useState<boolean>(false);
  const [renaming, setRenaming] = React.useState<boolean>(false);
  const [deleting, setDeleting] = React.useState<boolean>(false);
  const [lastSavedAt, setLastSavedAt] = React.useState<Date | null>(null);

  const router = useRouter();

  // Subscribe to Firestore doc by slug
  React.useEffect(() => {
    const refDoc = doc(db, "docs", slug);
    const unsub = onSnapshot(refDoc, (snap) => {
      if (!snap.exists()) {
        setDocData(null);
        setTitle("");
        setTagsText("");
        setContent("");
        return;
      }
      const data = snap.data() as DocData;
      setDocData(data);
      setTitle(data.title || "");
      setTagsText((data.tags || []).join(", "));
      setContent(data.content || "");
    });
    return () => unsub();
  }, [slug]);

  // Auto-save (debounced)
  React.useEffect(() => {
    const id = setTimeout(async () => {
      if (!title && !content) return;
      setSaving(true);
      const refDoc = doc(db, "docs", slug);
      await setDoc(
        refDoc,
        {
          title: title || "Untitled",
          content: content || "",
          tags: tagsText
            .split(",")
            .map((t) => t.trim())
            .filter(Boolean),
          updatedAt: serverTimestamp(),
          createdAt: docData?.createdAt || serverTimestamp(),
        },
        { merge: true }
      );
      setSaving(false);
      setLastSavedAt(new Date());
    }, 600);
    return () => clearTimeout(id);
  }, [title, content, tagsText, slug]);

  async function handleRename() {
    const next = prompt("New URL slug:", slug);
    if (!next) return;
    const newSlug = slugify(next);
    if (!newSlug || newSlug === slug) return;
    setRenaming(true);

    const fromRef = doc(db, "docs", slug);
    const toRef = doc(db, "docs", newSlug);

    const snap = await getDoc(fromRef);
    if (!snap.exists()) {
      setRenaming(false);
      return;
    }
    const data = snap.data() as DocData;

    // Create the new doc, then delete old one
    await setDoc(toRef, { ...data, updatedAt: serverTimestamp() }, { merge: true });
    await deleteDoc(fromRef);

    setRenaming(false);
    router.replace(`/docs/${newSlug}`);
  }

  async function handleDelete() {
    if (!confirm("Delete this document? This cannot be undone.")) return;
    setDeleting(true);
    await deleteDoc(doc(db, "docs", slug));
    setDeleting(false);
    router.replace("/docs");
  }

  async function uploadImageToStorage(file: File): Promise<string> {
    const path = `docs/${slug}/images/${Date.now()}-${file.name}`;
    const storageRef = ref(storage, path);
    const snap = await uploadBytes(storageRef, file);
    return await getDownloadURL(snap.ref);
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-2 md:flex-row md:items-center">
        <input
          className="w-full rounded border px-3 py-2"
          placeholder="Document title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
        <div className="flex gap-2 md:ml-auto">
          <button className="rounded border px-3 py-2 text-sm" onClick={handleRename} disabled={renaming}>
            {renaming ? "Renaming..." : "Rename"}
          </button>
          <button className="rounded border px-3 py-2 text-sm text-red-600" onClick={handleDelete} disabled={deleting}>
            {deleting ? "Deleting..." : "Delete"}
          </button>
        </div>
      </div>

      <input
        className="w-full rounded border px-3 py-2"
        placeholder="tags: comma, separated"
        value={tagsText}
        onChange={(e) => setTagsText(e.target.value)}
      />

      <MarkdownRXEditor value={content} onChange={setContent} onUploadImage={uploadImageToStorage} />

      <div className="text-sm text-muted-foreground">
        {saving ? "Saving..." : lastSavedAt ? `Saved ${lastSavedAt.toLocaleTimeString()}` : ""}
      </div>

      <details>
        <summary className="cursor-pointer">Preview (full page)</summary>
        <div className="mt-2 rounded border p-4">
          <MarkdownRXPreview value={content} />
        </div>
      </details>
    </div>
  );
}
'''
