docs_index_page_tsx = r'''
import Link from "next/link";
"use client";
import * as React from "react";
import { db } from "@/lib/firebase";
import {
  collection,
  onSnapshot,
  orderBy,
  query,
  setDoc,
  doc,
  serverTimestamp,
} from "firebase/firestore";

function slugify(input: string) {
  return input.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)+/g, "");
}

export default function DocsIndexPage() {
  const [items, setItems] = React.useState<any[]>([]);
  const [search, setSearch] = React.useState("");
  const [creating, setCreating] = React.useState(false);
  const [title, setTitle] = React.useState("");

  React.useEffect(() => {
    const q = query(collection(db, "docs"), orderBy("updatedAt", "desc"));
    const unsub = onSnapshot(q, (snap) => {
      const rows: any[] = [];
      snap.forEach((d) => rows.push({ id: d.id, ...(d.data() as any) }));
      setItems(rows);
    });
    return () => unsub();
  }, []);

  async function createDoc() {
    if (!title.trim()) return;
    setCreating(true);
    const slug = slugify(title);
    await setDoc(doc(db, "docs", slug), {
      title: title.trim(),
      content: "# New Document\n\nStart writing...",
      tags: [],
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
    }, { merge: true });
    setCreating(false);
    window.location.href = `/docs/${slug}`;
  }

  const filtered = items.filter((it) => {
    const hay = `${it.title} ${(it.tags || []).join(" ")}`.toLowerCase();
    const needle = search.toLowerCase();
    return hay.includes(needle);
  });

  return (
    <div className="mx-auto max-w-5xl p-6 space-y-6">
      <h1 className="text-2xl font-semibold">Documentation</h1>

      <div className="flex flex-col gap-2 md:flex-row md:items-center">
        <input
          className="w-full rounded border px-3 py-2"
          placeholder="Search by title or tag..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <div className="md:ml-auto flex gap-2">
          <input
