# components/DocEditor.tsx
# -------------------------------------------------------------
"use client";

import * as React from "react";
import { db, storage } from "@/lib/firebase";
import {
  doc,
  getDoc,
  onSnapshot,
  setDoc,
  updateDoc,
  deleteDoc,
  serverTimestamp,
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { MarkdownRXEditor, MarkdownRXPreview } from "@/components/MarkdownRX";
import { useRouter } from "next/navigation";

type DocData = {
  title: string;
  content: string;
  tags?: string[];
  createdAt?: any;
  updatedAt?: any;
};

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

export default function DocEditor({ slug }: { slug: string }) {
  const [title, setTitle] = React.useState<string>("");
  const [tagsText, setTagsText] = React.useState<string>("");
  const [content, setContent] = React.useState<string>("");
  const [saving, setSaving] = React.useState<boolean>(false);
  const [lastSavedAt, setLastSavedAt] = React.useState<Date | null>(null);
  const router = useRouter();

  // Subscribe to Firestore doc by slug
  React.useEffect(() => {
    const dref = doc(db, "docs", slug);
    const unsub = onSnapshot(dref, (snap) => {
      if (snap.exists()) {
        const data = snap.data() as DocData;
        setTitle(data.title || "");
        setContent(data.content || "");
        setTagsText((data.tags || []).join(", "));
      }
    });
    return () => unsub();
  }, [slug]);

  function normalizeForSave(title: string, md: string) {
    // Ensure a single H1 that matches the title at the top, blank line after, final newline
    const lines = md.split(/\r?\n/).filter(Boolean);
    const rest = lines.filter((l) => !/^#\s+/.test(l));
    const header = `# ${title.trim()}`;
    const body = rest.join("\n");
    let out = `${header}\n\n${body}`.replace(/\n{3,}/g, "\n\n");
    if (!out.endsWith("\n")) out += "\n";
    return out;
  }

  async function handleSave() {
    setSaving(true);
    try {
      const dref = doc(db, "docs", slug);
      await setDoc(
        dref,
        {
          title: title.trim() || "Untitled",
          content: normalizeForSave(title, content),
          tags: tagsText
            .split(",")
            .map((t) => t.trim())
            .filter(Boolean),
          updatedAt: serverTimestamp(),
          createdAt: (await getDoc(dref)).exists() ? undefined : serverTimestamp(),
        },
        { merge: true }
      );
      setLastSavedAt(new Date());
    } finally {
      setSaving(false);
    }
  }

  async function handleUploadImage(file: File): Promise<string> {
    const path = `docs/${slug}/images/${Date.now()}-${file.name}`;
    const sref = ref(storage, path);
    await uploadBytes(sref, file, { contentType: file.type });
    return await getDownloadURL(sref);
  }

  async function handleRename(newTitle: string) {
    const newSlug = slugify(newTitle);
    if (!newSlug || newSlug === slug) return;
    const oldRef = doc(db, "docs", slug);
    const newRef = doc(db, "docs", newSlug);
    const snap = await getDoc(oldRef);
    if (snap.exists()) {
      const data = snap.data() as DocData;
      await setDoc(newRef, { ...data, title: newTitle, updatedAt: serverTimestamp() });
      await deleteDoc(oldRef);
      router.replace(`/docs/${newSlug}`);
    }
  }

  async function handleDelete() {
    await deleteDoc(doc(db, "docs", slug));
    router.replace("/docs");
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-2 md:flex-row md:items-center">
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Document title"
          className="w-full rounded border px-3 py-2"
        />
        <button onClick={handleSave} className="rounded border px-3 py-2 md:ml-2">
          {saving ? "Saving..." : "Save"}
        </button>
        {lastSavedAt && <span className="text-sm text-muted-foreground">Saved {lastSavedAt.toLocaleTimeString()}</span>}
      </div>

      <input
        value={tagsText}
        onChange={(e) => setTagsText(e.target.value)}
        placeholder="tags (comma separated)"
        className="w-full rounded border px-3 py-2"
      />

      <MarkdownRXEditor value={content} onChange={setContent} onUploadImage={handleUploadImage} />

      <div className="flex gap-2">
        <button className="rounded border px-3 py-2" onClick={() => handleRename(title)}>Rename to Title Slug</button>
        <button className="rounded border px-3 py-2 text-red-600" onClick={handleDelete}>Delete</button>
      </div>

      <div>
        <h3 className="mb-2 font-semibold">Outline</h3>
        <Outline value={content} />
      </div>
    </div>
  );
}

function Outline({ value }: { value: string }) {
  const headings = React.useMemo(() => {
    return (value.match(/^#{1,6}\s+.+$/gm) || []).map((line) => {
      const level = (line.match(/^#+/)?.[0].length || 1);
      const text = line.replace(/^#{1,6}\s+/, "").trim();
      const id = text.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
      return { level, text, id };
    });
  }, [value]);

  return (
    <ul className="list-disc pl-6">
      {headings.map((h, i) => (
        <li key={i} className={`ml-${(h.level - 1) * 2}`}>
          <a href={`#${h.id}`} className="text-blue-600 hover:underline">{h.text}</a>
        </li>
      ))}
    </ul>
  );
}
