Reusable Tailwind-styled preview and editor. The editor provides toolbar buttons (bold, italic, code, H3/H2/H1 headings, lists, quote, table, code block), modes (edit/preview/split), and image upload via onUploadImage callback that returns a URL.

"use client";

import * as React from "react";
import { markdownToHtml } from "@/lib/markdownrx";

type PreviewProps = {
  value: string;
  className?: string;
  options?: Parameters<typeof markdownToHtml>[1];
};

export function MarkdownRXPreview({ value, className, options }: PreviewProps) {
  const [html, setHtml] = React.useState<string>("");

  React.useEffect(() => {
    let cancelled = false;
    markdownToHtml(value || "", options)
      .then((out) => {
        if (!cancelled) setHtml(out);
      })
      .catch(() => {
        if (!cancelled) setHtml("<pre>Failed to render markdown.</pre>");
      });
    return () => {
      cancelled = true;
    };
  }, [value, options]);

  return (
    <div
      className={["prose max-w-none", className].filter(Boolean).join(" ")}
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}

type EditorProps = {
  value: string;
  onChange: (value: string) => void;
  onUploadImage?: (file: File) => Promise<string>; // returns URL
  className?: string;
};

type Mode = "edit" | "preview" | "split";

export function MarkdownRXEditor({
  value,
  onChange,
  onUploadImage,
  className,
}: EditorProps) {
  const [mode, setMode] = React.useState<Mode>("split");
  const textareaRef = React.useRef<HTMLTextAreaElement | null>(null);

  function insertAtSelection(snippet: string) {
    const ta = textareaRef.current;
    if (!ta) return;
    const start = ta.selectionStart ?? 0;
    const end = ta.selectionEnd ?? 0;
    const next = value.slice(0, start) + snippet + value.slice(end);
    onChange(next);
    requestAnimationFrame(() => {
      ta.focus();
      const cursor = start + snippet.length;
      ta.setSelectionRange(cursor, cursor);
    });
  }

  function wrapSelection(before: string, after: string = before) {
    const ta = textareaRef.current;
    if (!ta) return;
    const start = ta.selectionStart ?? 0;
    const end = ta.selectionEnd ?? 0;
    const selected = value.slice(start, end);
    const next =
      value.slice(0, start) + before + selected + after + value.slice(end);
    onChange(next);
    requestAnimationFrame(() => {
      ta.focus();
      const cursor = start + before.length + selected.length + after.length;
      ta.setSelectionRange(cursor, cursor);
    });
  }

  async function onPickImage(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file || !onUploadImage) return;
    try {
      const url = await onUploadImage(file);
      const alt = file.name.replace(/\.\w+$/, "");
      const snippet = `![${alt}](${url})`;
      insertAtSelection(snippet);
    } catch (err) {
      console.error("Upload failed", err);
    } finally {
      e.target.value = "";
    }
  }

  const toolbarBtn =
    "rounded border px-2 py-1 text-sm hover:bg-muted/60 transition";

  const toolbar = (
    <div className="flex flex-wrap items-center gap-2 border-b bg-muted/40 px-2 py-2">
      <button className={toolbarBtn} onClick={() => wrapSelection("**", "**")}>
        Bold
      </button>
      <button className={toolbarBtn} onClick={() => wrapSelection("_", "_")}>
        Italic
      </button>
      <button className={toolbarBtn} onClick={() => wrapSelection("`", "`")}>
        Code
      </button>
      <button className={toolbarBtn} onClick={() => wrapSelection("# ", "")}>
        H1
      </button>
      <button className={toolbarBtn} onClick={() => wrapSelection("## ", "")}>
        H2
      </button>
      <button className={toolbarBtn} onClick={() => wrapSelection("### ", "")}>
        H3
      </button>
      <button className={toolbarBtn} onClick={() => wrapSelection("- ", "")}>
        List
      </button>
      <button className={toolbarBtn} onClick={() => wrapSelection("1. ", "")}>
        Numbered
      </button>
      <button className={toolbarBtn} onClick={() => wrapSelection("> ", "")}>
        Quote
      </button>
      <button
        className={toolbarBtn}
        onClick={() =>
          insertAtSelection("\n| Col A | Col B |\n| --- | --- |\n| A | B |\n")
        }
      >
        Table
      </button>
      <button
        className={toolbarBtn}
        onClick={() => wrapSelection("```\n", "\n```")}
      >
        Code Block
      </button>
      <label className={`${toolbarBtn} cursor-pointer`}>
        Image
        <input
          type="file"
          accept="image/*"
          className="hidden"
          onChange={onPickImage}
        />
      </label>
      <div className="ml-auto flex gap-1">
        <button
          className={`${toolbarBtn} ${
            mode === "edit" ? "bg-primary text-white" : ""
          }`}
          onClick={() => setMode("edit")}
        >
          Edit
        </button>
        <button
          className={`${toolbarBtn} ${
            mode === "preview" ? "bg-primary text-white" : ""
          }`}
          onClick={() => setMode("preview")}
        >
          Preview
        </button>
        <button
          className={`${toolbarBtn} ${
            mode === "split" ? "bg-primary text-white" : ""
          }`}
          onClick={() => setMode("split")}
        >
          Split
        </button>
      </div>
    </div>
  );

  const editor = (
    <textarea
      ref={textareaRef}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      className="h-[60vh] w-full resize-none border-0 p-3 outline-none"
      placeholder="# Write your documentation..."
    />
  );

  const preview = (
    <div className="h-[60vh] overflow-auto border-l p-4">
      <MarkdownRXPreview value={value} />
    </div>
  );

  return (
    <div
      className={[
        "rounded-md border bg-card shadow-sm",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      {toolbar}
      {mode === "edit" && <div>{editor}</div>}
      {mode === "preview" && (
        <div className="p-3">
          <MarkdownRXPreview value={value} />
        </div>
      )}
      {mode === "split" && (
        <div className="grid grid-cols-1 md:grid-cols-2">
          {editor}
          {preview}
        </div>
      )}
    </div>
  );
}

File: components/DocEditor.tsx
Client-side document editor wired to Firestore + Storage. It:
- Loads a document by slug with onSnapshot for live updates.
- Saves title, content, tags (optional).
- Uses serverTimestamp for createdAt/updatedAt.
- Renames the doc (creates new doc with new slug, copies data, deletes old).
- Deletes doc.
- Uploads images to Storage and inserts markdown image links.

"use client";

import * as React from "react";
import { db, storage } from "@/lib/firebase";
import {
  doc,
  getDoc,
  onSnapshot,
  serverTimestamp,
  setDoc,
  updateDoc,
  deleteDoc,
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { MarkdownRXEditor, MarkdownRXPreview } from "@/components/MarkdownRX";
import { useRouter } from "next/navigation";

type DocData = {
  title: string;
  content: string;
  tags?: string[];
  createdAt?: any;
  updatedAt?: any;
};

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

export default function DocEditor({ slug }: { slug: string }) {
  const [docData, setDocData] = React.useState<DocData | null>(null);
  const [title, setTitle] = React.useState<string>("");
  const [tagsText, setTagsText] = React.useState<string>("");
  const [content, setContent] = React.useState<string>("");
  const [saving, setSaving] = React.useState<boolean>(false);
  const [renaming, setRenaming] = React.useState<boolean>(false);
  const [deleting, setDeleting] = React.useState<boolean>(false);
  const [lastSavedAt, setLastSavedAt] = React.useState<Date | null>(null);

  const router = useRouter();

  React.useEffect(() => {
    const refDoc = doc(db, "docs", slug);
    const unsub = onSnapshot(refDoc, (snap) => {
      if (!snap.exists()) {
        setDocData(null);
        setTitle("");
        setTagsText("");
        setContent("");
        return;
      }
      const d = snap.data() as DocData;
      setDocData(d);
      setTitle(d.title || "");
      setContent(d.content || "");
      setTagsText((d.tags || []).join(", "));
    });
    return () => unsub();
  }, [slug]);

  async function ensureExists() {
    const refDoc = doc(db, "docs", slug);
    const snap = await getDoc(refDoc);
    if (!snap.exists()) {
      const payload: DocData = {
        title: title || "Untitled",
        content: content || "",
        tags: parseTags(tagsText),
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      };
      await setDoc(refDoc, payload);
    }
  }

  function parseTags(input: string): string[] {
    return input
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean);
  }

  async function save() {
    setSaving(true);
    try {
      await ensureExists();
      const refDoc = doc(db, "docs", slug);
      await updateDoc(refDoc, {
        title: title || "Untitled",
        content: content || "",
        tags: parseTags(tagsText),
        updatedAt: serverTimestamp(),
      });
      setLastSavedAt(new Date());
    } finally {
      setSaving(false);
    }
  }

  // Auto-save on changes after debounce
  React.useEffect(() => {
    const id = setTimeout(() => {
      if (title || content) {
        save().catch(console.error);
      }
    }, 800);
    return () => clearTimeout(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [title, content, tagsText]);

  async function rename() {
    const newSlugRaw = prompt("Enter new slug:", slug);
    if (!newSlugRaw) return;
    const newSlug = slugify(newSlugRaw);
    if (!newSlug) return alert("Invalid slug.");
    if (newSlug === slug) return;

    setRenaming(true);
    try {
      const oldRef = doc(db, "docs", slug);
      const oldSnap = await getDoc(oldRef);
      if (!oldSnap.exists()) throw new Error("Original document not found.");
      const data = oldSnap.data() as DocData;

      const newRef = doc(db, "docs", newSlug);
      await setDoc(newRef, {
        ...data,
        title: title || data.title || "Untitled",
        content: content ?? data.content ?? "",
        tags: parseTags(tagsText),
        updatedAt: serverTimestamp(),
        createdAt: data.createdAt || serverTimestamp(),
      });
      await deleteDoc(oldRef);
      router.replace(`/docs/${newSlug}`);
    } catch (e) {
      console.error(e);
      alert("Rename failed. Check console for details.");
    } finally {
      setRenaming(false);
    }
  }

  async function remove() {
    if (!confirm("Delete this document? This action cannot be undone.")) return;
    setDeleting(true);
    try {
      await deleteDoc(doc(db, "docs", slug));
      router.push("/docs");
    } catch (e) {
      console.error(e);
      alert("Delete failed.");
    } finally {
      setDeleting(false);
    }
  }

  async function handleUploadImage(file: File): Promise<string> {
    const path = `docs/${slug}/${Date.now()}-${file.name}`;
    const storageRef = ref(storage, path);
    await uploadBytes(storageRef, file);
    const url = await getDownloadURL(storageRef);
    return url;
  }

  return (
    <div className="mx-auto max-w-5xl space-y-4 p-4">
      <div className="flex items-center gap-2">
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Document title"
          className="w-full rounded border px-3 py-2"
        />
        <button
          onClick={save}
          disabled={saving}
          className="rounded border px-3 py-2 hover:bg-muted/60"
        >
          {saving ? "Saving..." : "Save"}
        </button>
        <button
          onClick={rename}
          disabled={renaming}
          className="rounded border px-3 py-2 hover:bg-muted/60"
        >
          {renaming ? "Renaming..." : "Rename"}
        </button>
        <button
          onClick={remove}
          disabled={deleting}
          className="rounded border px-3 py-2 text-red-600 hover:bg-red-50"
        >
          {deleting ? "Deleting..." : "Delete"}
        </button>
      </div>

      <input
        value={tagsText}
        onChange={(e) => setTagsText(e.target.value)}
        placeholder="tags (comma-separated)"
        className="w-full rounded border px-3 py-2"
      />

      <MarkdownRXEditor
        value={content}
        onChange={setContent}
        onUploadImage={handleUploadImage}
      />

      <div className="text-xs text-muted-foreground">
        {lastSavedAt
          ? `Last saved at ${lastSavedAt.toLocaleTimeString()}`
          : "No changes saved yet."}
      </div>

      <div className="rounded border p-3">
        <h3 className="mb-2 text-sm font-semibold uppercase tracking-wide text-muted-foreground">
          Live Preview
        </h3>
        <MarkdownRXPreview value={content} />
      </div>
    </div>
  );
}

