Lists/searches docs and creates a new doc. Uses a client component to subscribe to Firestore and navigate. "use client" is required due to onSnapshot, useState, and navigation.

"use client";

import * as React from "react";
import { db } from "@/lib/firebase";
import {
  collection,
  onSnapshot,
  orderBy,
  query,
  addDoc,
  serverTimestamp,
} from "firebase/firestore";
import Link from "next/link";
import { useRouter } from "next/navigation";

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

type DocListItem = {
  id: string; // slug if you store by slug; here we’ll store as auto-id in list and create by slug on edit page
  title: string;
  content: string;
  tags?: string[];
  createdAt?: any;
  updatedAt?: any;
};

export default function DocsPage() {
  const [docs, setDocs] = React.useState<DocListItem[]>([]);
  const [search, setSearch] = React.useState("");
  const [newTitle, setNewTitle] = React.useState("");
  const router = useRouter();

  React.useEffect(() => {
    const q = query(collection(db, "docs"), orderBy("updatedAt", "desc"));
    const unsub = onSnapshot(q, (snap) => {
      const out: DocListItem[] = [];
      snap.forEach((d) => out.push({ id: d.id, ...(d.data() as any) }));
      setDocs(out);
    });
    return () => unsub();
  }, []);

  const filtered = docs.filter((d) => {
    const t = (d.title || "").toLowerCase();
    const c = (d.content || "").toLowerCase();
    const s = search.toLowerCase();
    return t.includes(s) || c.includes(s) || (d.tags || []).join(",").toLowerCase().includes(s);
  });

  async function createNewDoc() {
    const base = newTitle || "Untitled";
    const slug = slugify(base);
    if (!slug) return alert("Invalid title.");
    // Initialize document by slug (so edit page can open it immediately)
    const res = await fetch(`/api/docs/create?slug=${encodeURIComponent(slug)}&title=${encodeURIComponent(base)}`, {
      method: "POST",
    });
    if (!res.ok) {
      const text = await res.text();
      alert(`Failed to create: ${text}`);
      return;
    }
    setNewTitle("");
    router.push(`/docs/${slug}`);
  }

  return (
    <div className="mx-auto max-w-5xl space-y-6 p-4">
      <div className="flex items-center gap-2">
        <input
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search docs..."
          className="w-full rounded border px-3 py-2"
        />
        <Link
          href="/docs"
          className="rounded border px-3 py-2 hover:bg-muted/60"
        >
          Clear
        </Link>
      </div>

      <div className="flex items-center gap-2">
        <input
          value={newTitle}
          onChange={(e) => setNewTitle(e.target.value)}
          placeholder="New doc title"
          className="w-full rounded border px-3 py-2"
        />
        <button
          onClick={createNewDoc}
          className="rounded border px-3 py-2 hover:bg-muted/60"
        >
          Create
        </button>
      </div>

      <ul className="divide-y rounded border">
        {filtered.map((d) => {
          const updated =
            d.updatedAt?.toDate?.().toLocaleString?.() || "—";
          return (
            <li key={d.id} className="flex items-center justify-between p-3">
              <div>
                <Link
                  className="text-blue-600 hover:underline"
                  href={`/docs/${encodeURIComponent(d.id)}`}
                >
                  {d.title || d.id}
                </Link>
                <div className="text-xs text-muted-foreground">
                  Updated: {updated}
                </div>
              </div>
              <div className="text-xs">{(d.tags || []).join(", ")}</div>
            </li>
          );
        })}
        {filtered.length === 0 && (
          <li className="p-3 text-sm text-muted-foreground">No docs found.</li>
        )}
      </ul>
    </div>
  );
}

