- In tailwind.config.js, enable @tailwindcss/typography for better preview rendering:
  - plugins: [require("@tailwindcss/typography")]
- Apply prose classes to MarkdownRXPreview for readable typography:
  - className="prose max-w-none"

How the pieces fit
- MarkdownRX pipeline (lib/markdownrx.ts) converts markdown to HTML with sanitization and syntax highlighting.
- components/MarkdownRX.tsx
  - MarkdownRXPreview consumes the pipeline to render sanitized HTML.
  - MarkdownRXEditor provides a toolbar and split/edit/preview modes; it calls onUploadImage for Storage uploads and inserts the markdown image syntax.
- components/DocEditor.tsx (client)
  - Connects to Firestore using onSnapshot for live sync.
  - Saves with serverTimestamp for createdAt/updatedAt.
  - Uploads images to Storage with uploadBytes/getDownloadURL and inserts the returned URL into the editor.
  - Supports rename (copy + delete old) and delete.
- app/docs/page.tsx (client)
  - Lists and searches docs via onSnapshot.
  - Creates a new doc through an API route and navigates to /docs/[slug].
- app/docs/[slug]/page.tsx (server wrapper)
  - Renders the client DocEditor and passes slug param.

"Use client" summary
- Add "use client" to:
  - lib/firebase.ts (if used in client; in this setup it is used by client components).
  - components/MarkdownRX.tsx (uses state/effect).
  - components/DocEditor.tsx (uses state/effect, Firebase SDK).
  - app/docs/page.tsx (uses state/effect, onSnapshot).
- app/docs/[slug]/page.tsx can remain a server component because it only composes client components without client hooks itself.

With this setup, you have a working multi-page documentation management system in a Next.js App Router project, styled with Tailwind, using Firestore for data, Storage for images, and a secure MarkdownRX pipeline for rendering.

```cpp
#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (ll)4e18;

struct Edge {
    int to;
    int w;
};
struct Node {
    int v;
    ll d;
    bool operator<(const Node& other) const { return d > other.d; }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if (!(cin >> n >> m >> k)) return 0;
    vector<vector<Edge>> g(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }

    auto dijkstra = [&](int src) {
        vector<ll> dist(n + 1, INF);
        priority_queue<Node> pq;
        dist[src] = 0;
        pq.push({src, 0});
        while (!pq.empty()) {
            auto cur = pq.top(); pq.pop();
            int u = cur.v;
            if (cur.d != dist[u]) continue;
            for (auto &e : g[u]) {
                int v = e.to;
                ll nd = dist[u] + e.w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.push({v, nd});
                }
            }
        }
        return dist;
    };

    vector<ll> d1 = dijkstra(1);
    vector<ll> dn = dijkstra(n);

    // Filter only nodes reachable from both ends
    vector<pair<ll,ll>> pts;
    pts.reserve(n);
    for (int i = 1; i <= n; ++i) {
        if (d1[i] < INF && dn[i] < INF) {
            pts.emplace_back(d1[i], dn[i]);
        }
    }

    // Build lower convex hull of points in (x=d1, y=dn) for minimizing |a*x - b*y|
    // Sort by x, then y
    sort(pts.begin(), pts.end());
    // Remove dominated points with same x keep minimal y
    vector<pair<ll,ll>> comp;
    for (size_t i = 0; i < pts.size(); ) {
        size_t j = i;
        ll besty = pts[i].second;
        while (j < pts.size() && pts[j].first == pts[i].first) {
            besty = min(besty, pts[j].second);
            ++j;
        }
        comp.emplace_back(pts[i].first, besty);
        i = j;
    }
    // Monotone chain lower hull by y with respect to x (we want tradeoff frontier decreasing y)
    // Keep only points that are not (x nondecreasing, y nonincreasing and convex)
    // We'll maintain hull such that for consecutive points p,q,r:
    // (q - p) and (r - q) should make slope (dy/dx) nondecreasing since dy negative.
    auto cross = [&](const pair<ll,ll>& a, const pair<ll,ll>& b, const pair<ll,ll>& c) {
        // cross((b-a),(c-a)) = (bx-ax)*(cy-ay) - (by-ay)*(cx-ax)
        __int128 x1 = (__int128)b.first - a.first;
        __int128 y1 = (__int128)b.second - a.second;
        __int128 x2 = (__int128)c.first - a.first;
        __int128 y2 = (__int128)c.second - a.second;
        __int128 cr = x1 * y2 - y1 * x2;
        if (cr < 0) return -1;
        if (cr > 0) return 1;
        return 0;
    };
    vector<pair<ll,ll>> hull;
    for (auto &p : comp) {
        // Enforce nonincreasing y to remove dominated by y as x increases
        if (!hull.empty() && p.second >= hull.back().second) continue;
        while (hull.size() >= 2) {
            auto a = hull[hull.size()-2];
            auto b = hull[hull.size()-1];
            // We want to keep lower convex curve -> remove b if turn is not clockwise
            // For minimizing |a*x - b*y| we need convexity; maintain that hull makes right turns
            if (cross(a, b, p) <= 0) hull.pop_back();
            else break;
        }
        hull.push_back(p);
    }
    // If hull is empty (shouldn't as path exists), fallback to comp
    if (hull.empty() && !comp.empty()) hull = comp;

    // For each query minimize |a*x - b*y| over hull (x increasing, y decreasing and convex).
    // f(t) = a*x - b*y is linear along segments; absolute value minimum occurs near where f changes sign.
    // Since f over hull is unimodal for given (a,b), we can ternary-like binary search on sign changes:
    // Compare f at mid and mid+1 to decide direction.
    int H = (int)hull.size();

    auto best_for = [&](ll a, ll b)->ll {
        if (H == 0) return 0;
        // If monotone in one direction, endpoints
        auto val = [&](int i)->__int128 {
            return (__int128)a * hull[i].first - (__int128)b * hull[i].second;
        };
        int lo = 0, hi = H - 1;
        while (hi - lo > 3) {
            int m1 = lo + (hi - lo) / 3;
            int m2 = hi - (hi - lo) / 3;
            __int128 f1 = val(m1);
            __int128 f2 = val(m2);
            // We want to minimize |f|
            __int128 g1 = f1 >= 0 ? f1 : -f1;
            __int128 g2 = f2 >= 0 ? f2 : -f2;
            if (g1 <= g2) hi = m2 - 1;
            else lo = m1 + 1;
        }
        __int128 best = -1;
        for (int i = lo; i <= hi; ++i) {
            __int128 v = val(i);
            if (v < 0) v = -v;
            if (best == -1 || v < best) best = v;
        }
        // best fits in 64-bit since a<=1e6, x<=sum w along shortest path <= 1e6*1e5 worst 1e11, product 1e17 fits in int128; cast to ll
        long long ans = (long long)best;
        return ans;
    };

    for (int i = 0; i < k; ++i) {
        ll a, b;
        cin >> a >> b;
        cout << best_for(a, b) << '\n';
    }
    return 0;
}
```

Below is a complete, self-contained Tkinter application that manages the tournament’s scoring. It is organized, validated, and commented to be maintainable. It includes:
- Participants (Teams and Individuals) with “one event only” support and optional chosen event.
- Events (Team or Individual) with optional per-event points.
- Results entry per event via ranked ordering with strong validation.
- Leaderboards for teams and individuals.
- Points configuration (global schemes + custom editor).
- Save/Load/New via JSON with validation and clear error handling.

To run: save as a .py file and execute with Python 3.8+.

```python
import json
from dataclasses import dataclass, asdict, field
from typing import Dict, List, Optional, Tuple

import tkinter as tk
from tkinter import ttk, messagebox, filedialog


# -------------------------
# Data Model
# -------------------------

@dataclass
class Team:
    id: int
    name: str
    members: List[str] = field(default_factory=list)
    one_event_only: bool = False
    chosen_event_id: Optional[int] = None  # Applies if one_event_only is True


@dataclass
class Individual:
    id: int
    name: str
    one_event_only: bool = False
    chosen_event_id: Optional[int] = None  # Applies if one_event_only is True


@dataclass
class Event:
    id: int
    name: str
    type: str  # "Team" or "Individual"
    genre: str = ""
    points_map: Optional[Dict[int, int]] = None  # Per-event override


class TournamentData:
    """
    Core model for the tournament. Handles validation, CRUD operations,
    results storage, points aggregation, and JSON (de)serialization.
    """
    def __init__(self):
        self.teams: Dict[int, Team] = {}
        self.individuals: Dict[int, Individual] = {}
        self.events: Dict[int, Event] = {}
        # event_id -> ordered list of entrant IDs
        self.results: Dict[int, List[int]] = {}
        # Global points table (default: F1 Top 10)
        self.points_map: Dict[int, int] = {
            1: 25, 2: 18, 3: 15, 4: 12, 5: 10, 6: 8, 7: 6, 8: 4, 9: 2, 10: 1
        }
        self.team_counter = 1
        self.indiv_counter = 1
        self.event_counter = 1

    # ---- Constraints ----
    def max_teams(self) -> int:
        return 4

    def max_team_members(self) -> int:
        return 5

    def max_individuals(self) -> int:
        return 20

    def max_events_per_type(self) -> int:
        # 5 Team events and 5 Individual events
        return 5

    # ---- Helpers ----
    @staticmethod
    def _clean_name(value: str) -> str:
        return (value or "").strip()

    def _validate_points_map(self, points: Dict[int, int]) -> None:
        if not isinstance(points, dict) or not points:
            raise ValueError("Points map must be a non-empty dictionary.")
        for k, v in points.items():
            if not isinstance(k, int) or k <= 0:
                raise ValueError("Rank keys must be positive integers.")
            if not isinstance(v, int) or v < 0:
                raise ValueError("Point values must be non-negative integers.")
        # Non-increasing across ranks: points[1] >= points[2] >= ...
        prev_points = None
        for r in sorted(points.keys()):
            if prev_points is not None and points[r] > prev_points:
                raise ValueError("Points should not increase for lower ranks.")
            prev_points = points[r]

    def get_points_for_event(self, event_id: int) -> Dict[int, int]:
        ev = self.events.get(event_id)
        if ev and ev.points_map:
            return ev.points_map
        return self.points_map

    # ---- CRUD for Teams ----
    def add_team(self, name: str, members: List[str], one_event_only: bool = False, chosen_event_id: Optional[int] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Team name cannot be empty.")
        if len(self.teams) >= self.max_teams():
            raise ValueError("Maximum number of teams reached (4).")
        if len(members) > self.max_team_members():
            raise ValueError("A team can have at most 5 members.")
        cleaned_members = [self._clean_name(m) for m in members if self._clean_name(m)]
        if not cleaned_members:
            raise ValueError("A team must have at least one member.")
        if any(t.name.lower() == name.lower() for t in self.teams.values()):
            raise ValueError("Team name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Team":
                raise ValueError("Chosen event must be a valid Team event.")
        team_id = self.team_counter
        self.team_counter += 1
        self.teams[team_id] = Team(id=team_id, name=name, members=cleaned_members,
                                   one_event_only=one_event_only, chosen_event_id=chosen_event_id)
        return team_id

    def edit_team(self, tid: int, name: str, members: List[str], one_event_only: bool, chosen_event_id: Optional[int]) -> None:
        if tid not in self.teams:
            raise ValueError("Team not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Team name cannot be empty.")
        if len(members) > self.max_team_members():
            raise ValueError("A team can have at most 5 members.")
        cleaned_members = [self._clean_name(m) for m in members if self._clean_name(m)]
        if not cleaned_members:
            raise ValueError("A team must have at least one member.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Team":
                raise ValueError("Chosen event must be a valid Team event.")
        if any(t.name.lower() == name.lower() and t.id != tid for t in self.teams.values()):
            raise ValueError("Team name must be unique.")
        t = self.teams[tid]
        t.name = name
        t.members = cleaned_members
        t.one_event_only = one_event_only
        t.chosen_event_id = chosen_event_id

    def remove_team(self, tid: int) -> None:
        if tid not in self.teams:
            raise ValueError("Team not found.")
        # Remove from any Team event results
        for ev_id, places in list(self.results.items()):
            ev = self.events.get(ev_id)
            if ev and ev.type == "Team":
                self.results[ev_id] = [pid for pid in places if pid != tid]
        del self.teams[tid]
        # Keep consistency after removals
        self._clean_invalid_one_event_refs()

    # ---- CRUD for Individuals ----
    def add_individual(self, name: str, one_event_only: bool = False, chosen_event_id: Optional[int] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Individual name cannot be empty.")
        if len(self.individuals) >= self.max_individuals():
            raise ValueError("Maximum number of individuals reached (20).")
        if any(i.name.lower() == name.lower() for i in self.individuals.values()):
            raise ValueError("Individual name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Individual":
                raise ValueError("Chosen event must be a valid Individual event.")
        iid = self.indiv_counter
        self.indiv_counter += 1
        self.individuals[iid] = Individual(
            id=iid,
            name=name,
            one_event_only=one_event_only,
            chosen_event_id=chosen_event_id
        )
        return iid

    def edit_individual(self, iid: int, name: str, one_event_only: bool, chosen_event_id: Optional[int]) -> None:
        if iid not in self.individuals:
            raise ValueError("Individual not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Individual name cannot be empty.")
        if any(p.name.lower() == name.lower() and p.id != iid for p in self.individuals.values()):
            raise ValueError("Individual name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Individual":
                raise ValueError("Chosen event must be a valid Individual event.")
        p = self.individuals[iid]
        p.name = name
        p.one_event_only = one_event_only
        p.chosen_event_id = chosen_event_id

    def remove_individual(self, iid: int) -> None:
        if iid not in self.individuals:
            raise ValueError("Individual not found.")
        for ev_id, places in list(self.results.items()):
            ev = self.events.get(ev_id)
            if ev and ev.type == "Individual":
                self.results[ev_id] = [pid for pid in places if pid != iid]
        del self.individuals[iid]
        self._clean_invalid_one_event_refs()

    # ---- CRUD for Events ----
    def add_event(self, name: str, etype: str, genre: str = "", points_map: Optional[Dict[int, int]] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Event name cannot be empty.")
        if etype not in ("Team", "Individual"):
            raise ValueError("Event type must be 'Team' or 'Individual'.")
        count_type = sum(1 for e in self.events.values() if e.type == etype)
        if count_type >= self.max_events_per_type():
            raise ValueError(f"Maximum number of {etype} events reached (5).")
        if any(e.name.lower() == name.lower() for e in self.events.values()):
            raise ValueError("Event name must be unique.")
        if points_map:
            self._validate_points_map(points_map)
        eid = self.event_counter
        self.event_counter += 1
        self.events[eid] = Event(id=eid, name=name, type=etype, genre=self._clean_name(genre), points_map=points_map)
        return eid

    def edit_event(self, eid: int, name: str, etype: str, genre: str, points_map: Optional[Dict[int, int]]) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Event name cannot be empty.")
        if etype not in ("Team", "Individual"):
            raise ValueError("Event type must be 'Team' or 'Individual'.")
        if any(e.name.lower() == name.lower() and e.id != eid for e in self.events.values()):
            raise ValueError("Event name must be unique.")
        if points_map:
            self._validate_points_map(points_map)
        old = self.events[eid]
        # If the type changes, clear any existing results (to avoid cross-type mismatch)
        if old.type != etype and eid in self.results:
            self.results[eid] = []
        old.name = name
        old.type = etype
        old.genre = self._clean_name(genre)
        old.points_map = points_map
        self._clean_invalid_one_event_refs()

    def remove_event(self, eid: int) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        # Remove results for this event
        self.results.pop(eid, None)
        # Clear chosen_event_id references if they point to this event
        for t in self.teams.values():
            if t.chosen_event_id == eid:
                t.chosen_event_id = None
        for i in self.individuals.values():
            if i.chosen_event_id == eid:
                i.chosen_event_id = None
        del self.events[eid]

    # ---- Results & Scoring ----
    def set_event_results(self, eid: int, ordered_ids: List[int]) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        ev = self.events[eid]
        # Validate entrants exist and match event type
        if ev.type == "Team":
            valid_ids = set(self.teams.keys())
        else:
            valid_ids = set(self.individuals.keys())
        cleaned = [pid for pid in ordered_ids if pid in valid_ids]
        if len(cleaned) != len(set(cleaned)):
            raise ValueError("Duplicate participants in results.")
        # Respect one-event-only constraints
        for pid in cleaned:
            if ev.type == "Team":
                t = self.teams[pid]
                if t.one_event_only and t.chosen_event_id is not None and t.chosen_event_id != eid:
                    raise ValueError(f"Team '{t.name}' can only participate in event {t.chosen_event_id}.")
            else:
                p = self.individuals[pid]
                if p.one_event_only and p.chosen_event_id is not None and p.chosen_event_id != eid:
                    raise ValueError(f"Individual '{p.name}' can only participate in event {p.chosen_event_id}.")
        self.results[eid] = cleaned

    def compute_leaderboards(self) -> Tuple[List[Tuple[int, int]], List[Tuple[int, int]]]:
        team_points: Dict[int, int] = {tid: 0 for tid in self.teams}
        indiv_points: Dict[int, int] = {iid: 0 for iid in self.individuals}
        for eid, placements in self.results.items():
            ev = self.events.get(eid)
            if not ev:
                continue
            points_map = self.get_points_for_event(eid)
            for rank, pid in enumerate(placements, start=1):
                pts = points_map.get(rank, 0)
                if ev.type == "Team":
                    if pid in team_points:
                        team_points[pid] += pts
                else:
                    if pid in indiv_points:
                        indiv_points[pid] += pts
        # Sort by points desc, then id asc for stability
        team_board = sorted(team_points.items(), key=lambda x: (-x[1], x[0]))
        indiv_board = sorted(indiv_points.items(), key=lambda x: (-x[1], x[0]))
        return team_board, indiv_board

    # ---- JSON Persistence ----
    def to_json(self) -> str:
        payload = {
            "teams": [asdict(t) for t in self.teams.values()],
            "individuals": [asdict(i) for i in self.individuals.values()],
            "events": [asdict(e) for e in self.events.values()],
            "results": {str(k): v for k, v in self.results.items()},
            "points_map": self.points_map,
            "counters": {
                "team_counter": self.team_counter,
                "indiv_counter": self.indiv_counter,
                "event_counter": self.event_counter,
            },
        }
        return json.dumps(payload, indent=2)

    @staticmethod
    def from_json(s: str) -> "TournamentData":
        data = json.loads(s)
        td = TournamentData()
        for t in data.get("teams", []):
            td.teams[t["id"]] = Team(**t)
        for i in data.get("individuals", []):
            td.individuals[i["id"]] = Individual(**i)
        for e in data.get("events", []):
            td.events[e["id"]] = Event(**e)
        td.results = {int(k): v for k, v in data.get("results", {}).items()}
        if "points_map" in data and data["points_map"]:
            td._validate_points_map({int(k): int(v) for k, v in data["points_map"].items()})
            td.points_map = {int(k): int(v) for k, v in data["points_map"].items()}
        c = data.get("counters", {})
        td.team_counter = int(c.get("team_counter", 1))
        td.indiv_counter = int(c.get("indiv_counter", 1))
        td.event_counter = int(c.get("event_counter", 1))
        td._clean_invalid_one_event_refs()
        return td

    # ---- Internal consistency helpers ----
    def _clean_invalid_one_event_refs(self) -> None:
        # Remove chosen_event_id if event no longer exists or mismatched type
        for t in self.teams.values():
            if t.chosen_event_id is not None:
                ev = self.events.get(t.chosen_event_id)
                if ev is None or ev.type != "Team":
                    t.chosen_event_id = None
        for i in self.individuals.values():
            if i.chosen_event_id is not None:
                ev = self.events.get(i.chosen_event_id)
                if ev is None or ev.type != "Individual":
                    i.chosen_event_id = None


