class TournamentApp(tk.Tk):
    """Main application window with notebook tabs for Entities, Events, Results, and Leaderboards."""

    def __init__(self):
        super().__init__()
        self.title("E-Sports Tournament Scoring")
        self.geometry("1100x700")
        self.minsize(1000, 640)

        self.data = TournamentData()

        self._make_menu()
        self._make_notebook()
        self._make_entities_tab()
        self._make_events_tab()
        self._make_results_tab()
        self._make_leaderboards_tab()

    # ---- Menu ----
    def _make_menu(self):
        menubar = tk.Menu(self)
        filemenu = tk.Menu(menubar, tearoff=0)
        filemenu.add_command(label="New", command=self._new_data)
        filemenu.add_command(label="Open...", command=self._load_data)
        filemenu.add_command(label="Save As...", command=self._save_data)
        filemenu.add_separator()
        filemenu.add_command(label="Exit", command=self.destroy)
        menubar.add_cascade(label="File", menu=filemenu)

        settings = tk.Menu(menubar, tearoff=0)
        settings.add_command(label="Edit Global Points Table", command=self._edit_global_points)
        menubar.add_cascade(label="Settings", menu=settings)

        self.config(menu=menubar)

    # ---- Notebook ----
    def _make_notebook(self):
        self.nb = ttk.Notebook(self)
        self.nb.pack(fill=tk.BOTH, expand=True)
        self.tab_entities = ttk.Frame(self.nb)
        self.tab_events = ttk.Frame(self.nb)
        self.tab_results = ttk.Frame(self.nb)
        self.tab_boards = ttk.Frame(self.nb)
        self.nb.add(self.tab_entities, text="Participants")
        self.nb.add(self.tab_events, text="Events")
        self.nb.add(self.tab_results, text="Results")
        self.nb.add(self.tab_boards, text="Leaderboards")

    # ---- Entities Tab (Teams & Individuals) ----
    def _make_entities_tab(self):
        container = ttk.Panedwindow(self.tab_entities, orient=tk.HORIZONTAL)
        container.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)

        # Teams panel
        team_frame = ttk.Labelframe(container, text="Teams")
        container.add(team_frame, weight=1)
        self._teams_tree = ttk.Treeview(team_frame, columns=("name", "members", "one", "chosen"), show="headings", height=12)
        for col, txt, w in (("name", "Team", 160), ("members", "Members", 260), ("one", "One-Event?", 90), ("chosen", "Chosen Event", 140)):
            self._teams_tree.heading(col, text=txt)
            self._teams_tree.column(col, width=w, anchor=tk.W)
        self._teams_tree.pack(fill=tk.BOTH, expand=True, padx=6, pady=6)

        tf_buttons = ttk.Frame(team_frame)
        tf_buttons.pack(fill=tk.X, padx=6, pady=4)
        ttk.Button(tf_buttons, text="Add Team", command=self._add_team_dialog).pack(side=tk.LEFT)
        ttk.Button(tf_buttons, text="Edit", command=self._edit_team_dialog).pack(side=tk.LEFT, padx=6)
        ttk.Button(tf_buttons, text="Remove", command=self._remove_selected_team).pack(side=tk.LEFT)

        # Individuals panel
        indiv_frame = ttk.Labelframe(container, text="Individuals")
        container.add(indiv_frame, weight=1)
        self._indiv_tree = ttk.Treeview(indiv_frame, columns=("name", "one", "chosen"), show="headings", height=12)
        for col, txt, w in (("name", "Name", 180), ("one", "One-Event?", 90), ("chosen", "Chosen Event", 160)):
            self._indiv_tree.heading(col, text=txt)
            self._indiv_tree.column(col, width=w, anchor=tk.W)
        self._indiv_tree.pack(fill=tk.BOTH, expand=True, padx=6, pady=6)

        if_buttons = ttk.Frame(indiv_frame)
        if_buttons.pack(fill=tk.X, padx=6, pady=4)
        ttk.Button(if_buttons, text="Add Individual", command=self._add_individual_dialog).pack(side=tk.LEFT)
        ttk.Button(if_buttons, text="Edit", command=self._edit_individual_dialog).pack(side=tk.LEFT, padx=6)
