        frame.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)

        self._events_tree = ttk.Treeview(frame, columns=("name", "type", "genre", "points"), show="headings", height=16)
        for col, txt, w in (("name", "Event", 180), ("type", "Type", 90), ("genre", "Genre", 140), ("points", "Per-Event Points?", 150)):
            self._events_tree.heading(col, text=txt)
            self._events_tree.column(col, width=w, anchor=tk.W)
        self._events_tree.pack(fill=tk.BOTH, expand=True, padx=6, pady=6)

        btns = ttk.Frame(frame)
