    # ---- Menu actions ----
    def _new_data(self):
        if not messagebox.askyesno("Confirm", "Discard current data and start new?"):
            return
        self.data = TournamentData()
        self._refresh_all()

    def _save_data(self):
        fp = filedialog.asksaveasfilename(defaultextension=".json", filetypes=[("JSON", "*.json")])
        if not fp:
            return
        try:
            with open(fp, "w", encoding="utf-8") as f:
                f.write(self.data.to_json())
            messagebox.showinfo("Saved", f"Saved to {fp}")
        except Exception as e:
            messagebox.showerror("Error", str(e))

    def _load_data(self):
        fp = filedialog.askopenfilename(filetypes=[("JSON", "*.json")])
        if not fp:
            return
        try:
            with open(fp, "r", encoding="utf-8") as f:
                s = f.read()
            self.data = TournamentData.from_json(s)
            self._refresh_all()
            messagebox.showinfo("Loaded", f"Loaded from {fp}")
        except Exception as e:
            messagebox.showerror("Error", str(e))

