    # ---- Results actions ----
    def _refresh_event_combobox(self):
        items = [f"{eid}: {e.name} ({e.type})" for eid, e in sorted(self.data.events.items())]
        self._results_event_cb["values"] = items
        self._results_event_var.set("")
        self._entrants_list.delete(0, tk.END)
        self._candidates_list.delete(0, tk.END)

    def _parse_selected_event_id(self) -> Optional[int]:
        val = self._results_event_var.get().strip()
        if not val:
            return None
        try:
            return int(val.split(":", 1)[0])
        except Exception:
            return None

    def _load_entrants_for_event(self):
        eid = self._parse_selected_event_id()
        if eid is None or eid not in self.data.events:
            messagebox.showwarning("Select", "Please select a valid event.")
            return
        ev = self.data.events[eid]
        # Populate candidates based on type
        self._candidates_list.delete(0, tk.END)
        if ev.type == "Team":
            candidates = [(tid, t.name) for tid, t in sorted(self.data.teams.items())]
        else:
            candidates = [(iid, p.name) for iid, p in sorted(self.data.individuals.items())]
        for pid, name in candidates:
            self._candidates_list.insert(tk.END, f"{pid}: {name}")
        # Load existing results if any
        self._entrants_list.delete(0, tk.END)
        for pid in self.data.results.get(eid, []):
            if ev.type == "Team":
                name = self.data.teams.get(pid).name if self.data.teams.get(pid) else f"Team {pid}"
            else:
                name = self.data.individuals.get(pid).name if self.data.individuals.get(pid) else f"Player {pid}"
            self._entrants_list.insert(tk.END, f"{pid}: {name}")

    def _add_selected_candidate(self):
        sel = self._candidates_list.curselection()
        if not sel:
            return
        line = self._candidates_list.get(sel[0])
        try:
            pid = int(line.split(":", 1)[0])
        except Exception:
            return
        # Avoid duplicates in entrants list
        for i in range(self._entrants_list.size()):
            if self._entrants_list.get(i).startswith(f"{pid}:"):
                return
        self._entrants_list.insert(tk.END, line)

    def _move_selected(self, direction: int):
        sel = self._entrants_list.curselection()
        if not sel:
            return
        idx = sel[0]
        new_idx = idx + direction
        if new_idx < 0 or new_idx >= self._entrants_list.size():
            return
        text = self._entrants_list.get(idx)
        self._entrants_list.delete(idx)
        self._entrants_list.insert(new_idx, text)
        self._entrants_list.selection_set(new_idx)

    def _remove_selected_entrant(self):
        sel = self._entrants_list.curselection()
        if not sel:
            return
        self._entrants_list.delete(sel[0])

    def _save_event_results(self):
        eid = self._parse_selected_event_id()
        if eid is None or eid not in self.data.events:
            messagebox.showwarning("Select", "Please select a valid event.")
            return
        ids: List[int] = []
        for i in range(self._entrants_list.size()):
            try:
                pid = int(self._entrants_list.get(i).split(":", 1)[0])
                ids.append(pid)
            except Exception:
                pass
        try:
            self.data.set_event_results(eid, ids)
            messagebox.showinfo("Saved", "Results saved for event.")
            self._refresh_leaderboards()
        except Exception as e:
            messagebox.showerror("Invalid Results", str(e))

    # ---- Leaderboards ----
    def _refresh_leaderboards(self):
        # Clear
        for tv in (self._team_board, self._indiv_board):
            for iid in tv.get_children():
                tv.delete(iid)
        team_board, indiv_board = self.data.compute_leaderboards()
        for tid, pts in team_board:
            name = self.data.teams.get(tid).name if self.data.teams.get(tid) else f"Team {tid}"
            self._team_board.insert("", tk.END, values=(name, pts))
        for iid, pts in indiv_board:
            name = self.data.individuals.get(iid).name if self.data.individuals.get(iid) else f"Player {iid}"
            self._indiv_board.insert("", tk.END, values=(name, pts))

    # ---- Utilities ----
    @staticmethod
    def _get_selected_id(tree: ttk.Treeview) -> Optional[int]:
        sel = tree.selection()
        if not sel:
            return None
        try:
            return int(tree.item(sel[0], "text") or tree.item(sel[0], "values")[0])
        except Exception:
            # We store id in iid field; safer approach is mapping. We'll keep simple by storing in iid.
            try:
                return int(sel[0])
            except Exception:
                return None

    def _refresh_all(self):
        self._refresh_entities()
        self._refresh_events()
        self._refresh_event_combobox()
        self._refresh_leaderboards()

    def _refresh_entities(self):
        # Teams
        for iid in self._teams_tree.get_children():
            self._teams_tree.delete(iid)
        for tid, t in sorted(self.data.teams.items()):
            chosen = self._format_event_label(t.chosen_event_id)
            iid = str(tid)
            self._teams_tree.insert("", tk.END, iid=iid, values=(t.name, ", ".join(t.members), "Yes" if t.one_event_only else "No", chosen))
        # Individuals
        for iid in self._indiv_tree.get_children():
            self._indiv_tree.delete(iid)
        for pid, p in sorted(self.data.individuals.items()):
            chosen = self._format_event_label(p.chosen_event_id)
            iid = str(pid)
            self._indiv_tree.insert("", tk.END, iid=iid, values=(p.name, "Yes" if p.one_event_only else "No", chosen))

    def _refresh_events(self):
        for iid in self._events_tree.get_children():
            self._events_tree.delete(iid)
        for eid, e in sorted(self.data.events.items()):
            has_custom = "Yes" if e.points_map else "No"
            iid = str(eid)
            self._events_tree.insert("", tk.END, iid=iid, values=(e.name, e.type, e.genre, has_custom))

    def _format_event_label(self, eid: Optional[int]) -> str:
        if eid is None:
            return "(none)"
        ev = self.data.events.get(eid)
        return f"{eid}: {ev.name}" if ev else f"{eid}: (deleted)"


