class TeamDialog(tk.Toplevel):
    def __init__(self, master: TournamentApp, data: TournamentData, team: Optional[Team] = None, on_save=None):
        super().__init__(master)
        self.title("Team")
        self.resizable(False, False)
        self.data = data
        self.team = team
        self.on_save = on_save

        frm = ttk.Frame(self)
        frm.pack(padx=10, pady=10, fill=tk.BOTH, expand=True)

        ttk.Label(frm, text="Team name:").grid(row=0, column=0, sticky=tk.W)
        self.name_var = tk.StringVar(value=team.name if team else "")
        ttk.Entry(frm, textvariable=self.name_var, width=40).grid(row=0, column=1, sticky=tk.W)

        ttk.Label(frm, text="Members (one per line, up to 5):").grid(row=1, column=0, sticky=tk.NW)
        self.members_txt = tk.Text(frm, width=40, height=6)
        if team:
            self.members_txt.insert("1.0", "\n".join(team.members))
        self.members_txt.grid(row=1, column=1, sticky=tk.W)

        self.one_only_var = tk.BooleanVar(value=team.one_event_only if team else False)
        ttk.Checkbutton(frm, text="One event only", variable=self.one_only_var).grid(row=2, column=1, sticky=tk.W, pady=(6, 0))

        ttk.Label(frm, text="Chosen event (Team events only):").grid(row=3, column=0, sticky=tk.W)
        self.chosen_var = tk.StringVar()
        team_events = [f"{eid}: {e.name}" for eid, e in self.data.events.items() if e.type == "Team"]
        self.chosen_cb = ttk.Combobox(frm, textvariable=self.chosen_var, values=["(none)"] + team_events, state="readonly", width=38)
        self.chosen_cb.grid(row=3, column=1, sticky=tk.W)
        if team and team.chosen_event_id and team.chosen_event_id in self.data.events:
            self.chosen_var.set(f"{team.chosen_event_id}: {self.data.events[team.chosen_event_id].name}")
        else:
            self.chosen_var.set("(none)")

        btns = ttk.Frame(frm)
        btns.grid(row=4, column=0, columnspan=2, pady=8)
        ttk.Button(btns, text="Cancel", command=self.destroy).pack(side=tk.RIGHT)
        ttk.Button(btns, text="Save", command=self._save).pack(side=tk.RIGHT, padx=6)

    def _save(self):
        name = self.name_var.get().strip()
        members = [m.strip() for m in self.members_txt.get("1.0", tk.END).splitlines() if m.strip()]
        if len(members) > 5:
            messagebox.showerror("Error", "At most 5 members allowed.")
            return
        chosen = None
        val = self.chosen_var.get()
        if val and val != "(none)":
            try:
                chosen = int(val.split(":", 1)[0])
            except Exception:
                chosen = None
        one_only = self.one_only_var.get()
        try:
            if self.team:
                self.on_save(name, members, one_only, chosen)
            else:
                self.on_save(name, members, one_only, chosen)
            self.destroy()
        except Exception as e:
            messagebox.showerror("Error", str(e))


