class EventDialog(tk.Toplevel):
    def __init__(self, master: TournamentApp, event: Optional[Event] = None, on_save=None):
        super().__init__(master)
        self.title("Event")
        self.resizable(False, False)
        self.event = event
        self.on_save = on_save

        frm = ttk.Frame(self)
        frm.pack(padx=10, pady=10, fill=tk.BOTH, expand=True)

        ttk.Label(frm, text="Name:").grid(row=0, column=0, sticky=tk.W)
        self.name_var = tk.StringVar(value=event.name if event else "")
        ttk.Entry(frm, textvariable=self.name_var, width=40).grid(row=0, column=1, sticky=tk.W)

        ttk.Label(frm, text="Type:").grid(row=1, column=0, sticky=tk.W)
        self.type_var = tk.StringVar(value=event.type if event else "Team")
        ttk.Combobox(frm, textvariable=self.type_var, values=["Team", "Individual"], state="readonly", width=38).grid(row=1, column=1, sticky=tk.W)

        ttk.Label(frm, text="Genre (optional):").grid(row=2, column=0, sticky=tk.W)
        self.genre_var = tk.StringVar(value=event.genre if event else "")
        ttk.Entry(frm, textvariable=self.genre_var, width=40).grid(row=2, column=1, sticky=tk.W)

        # Custom points editor (simple CSV rank:points lines)
        ttk.Label(frm, text="Custom points (rank:points per line, optional):").grid(row=3, column=0, sticky=tk.NW)
        self.points_txt = tk.Text(frm, width=40, height=6)
        if event and event.points_map:
            lines = [f"{r}:{p}" for r, p in sorted(event.points_map.items())]
            self.points_txt.insert("1.0", "\n".join(lines))
        self.points_txt.grid(row=3, column=1, sticky=tk.W)

        btns = ttk.Frame(frm)
        btns.grid(row=4, column=0, columnspan=2, pady=8)
        ttk.Button(btns, text="Cancel", command=self.destroy).pack(side=tk.RIGHT)
        ttk.Button(btns, text="Save", command=self._save).pack(side=tk.RIGHT, padx=6)

    def _parse_points(self) -> Optional[Dict[int, int]]:
        raw = [ln.strip() for ln in self.points_txt.get("1.0", tk.END).splitlines() if ln.strip()]
        if not raw:
            return None
        points: Dict[int, int] = {}
        for ln in raw:
            if ":" not in ln:
                raise ValueError("Each line must be 'rank:points'.")
            r, p = ln.split(":", 1)
            r_i = int(r.strip())
            p_i = int(p.strip())
            if r_i <= 0 or p_i < 0:
                raise ValueError("Rank must be > 0 and points >= 0.")
            points[r_i] = p_i
        return dict(sorted(points.items()))

    def _save(self):
        name = self.name_var.get().strip()
        etype = self.type_var.get().strip()
        genre = self.genre_var.get().strip()
        try:
