        except Exception as e:
            messagebox.showerror("Invalid Points", str(e))
            return
        try:
            if self.event:
                self.on_save(name, etype, genre, points)
            else:
                self.on_save(name, etype, genre, points)
            self.destroy()
        except Exception as e:
            messagebox.showerror("Error", str(e))


