% 2D Source Panel Method for External Flow Around a Closed Zero-Thickness Contour
% Self-contained MATLAB script. No toolboxes required.
% Features:
% - Reads ordered (x,y) boundary points from a text file (two columns, whitespace-separated)
% - Closes the contour automatically (last point connects to first)
% - Prompts for U_inf, alpha (deg), rho, and a vector of panel counts to test (e.g., [40 80 160])
% - Constant-strength source panels, no circulation per panel; no-penetration BC
% - Solves for source strengths, computes tangential velocity, Cp, and lift using Kutta–Joukowski
% - Estimates net circulation from surface tangential velocity
% - Performs accuracy study by resampling geometry to requested panel counts
% - If filename contains "circle", compares against analytical cylinder solution
% - Optionally reads experimental comparison file: either Cp data (s/C vs Cp) or a single scalar Cl_exp
% - Writes Cp distributions to Cp_Nxx.txt and plots Cp vs s/C
% - Prints residuals and Cl for each discretization
%
% Usage:
% 1) Prepare a text file with two columns: x y (closed automatically).
% 2) Run this script; provide inputs when prompted.
% 3) Optional: Provide a second file with experimental data (leave blank to skip).
%
% Limitations:
% - Zero-thickness, impermeable body. No Kutta condition (no lift on symmetric body without angle-of-attack-induced circulation).
% - For bodies that generate lift physically, this pure-source model will predict near-zero lift unless asymmetry/aoa-induced effective circulation is present via discretization.
% - Uses straight, constant-source panels and mid-point collocation.

clear; clc; close all;

fprintf('=== 2D Source Panel Method (Constant-Strength) ===\n');

% --------------------------
% Input file: geometry
% --------------------------
geomFile = input('Enter path to geometry file (two columns: x y): ', 's');
if isempty(geomFile)
    error('No geometry file provided.');
end
if ~isfile(geomFile)
    error('Geometry file not found: %s', geomFile);
end

% Read geometry
try
    data = readmatrix(geomFile);
catch
    error('Failed to read geometry file. Ensure it is plain text with two columns (x y).');
end

if size(data,2) < 2
    error('Geometry file must contain at least two columns: x y');
end
x_in = data(:,1);
y_in = data(:,2);

% Validate
if any(isnan(x_in)) || any(isnan(y_in))
    error('Geometry contains NaN values.');
end
if numel(x_in) < 3
    error('Geometry must contain at least 3 points.');
end

% Remove possible duplicate last=first in input to avoid double closure
if hypot(x_in(end)-x_in(1), y_in(end)-y_in(1)) < 1e-12
    x_in = x_in(1:end-1);
    y_in = y_in(1:end-1);
end

% --------------------------
% Runtime parameters
% --------------------------
U_inf = input('Free-stream speed U_inf (m/s): ');
alpha_deg = input('Angle of attack alpha (degrees): ');
rho = input('Air density rho (kg/m^3): ');
Nlist_str = input('Panel counts vector (e.g., [40 80 160]): ', 's');
if isempty(Nlist_str)
    error('Panel counts not provided.');
end
Nlist = str2num(Nlist_str); %#ok<ST2NM>
if isempty(Nlist) || any(Nlist < 3)
    error('Invalid panel count list.');
end
Nlist = unique(Nlist(:).'); % ensure row and unique increasing order
alpha = deg2rad(alpha_deg);

% Optional comparison file (experimental Cp or Cl)
optFile = input('Optional comparison file (Cp s/C vs Cp two columns, or single scalar Cl_exp). Leave blank to skip: ', 's');
useExpCp = false; useExpCl = false; sExp = []; CpExp = []; Cl_exp = [];
if ~isempty(optFile)
    if ~isfile(optFile)
        fprintf('Warning: comparison file not found, skipping comparisons.\n');
    else
        try
            expData = readmatrix(optFile);
            if isscalar(expData)
                Cl_exp = expData(1);
                useExpCl = true;
                fprintf('Loaded experimental Cl = %.6f\n', Cl_exp);
            elseif size(expData,2) >= 2
                sExp = expData(:,1); CpExp = expData(:,2);
                if any(isnan(sExp)) || any(isnan(CpExp))
                    fprintf('Warning: experimental Cp contains NaNs. Skipping Cp comparison.\n');
                else
                    useExpCp = true;
                    fprintf('Loaded experimental Cp with %d points.\n', numel(sExp));
                end
            else
                fprintf('Warning: comparison file not recognized. Skipping.\n');
            end
        catch
            fprintf('Warning: failed to read comparison file. Skipping.\n');
        end
    end
end

% Detect "circle" in filename for analytical comparison
isCircleCase = contains(lower(geomFile), 'circle');

% --------------------------
% Helper functions (nested)
% --------------------------
    function [xp, yp, s_c] = resampleClosedPolyline(x, y, N)
        % Resample a closed polyline (x,y) to N evenly spaced points by arc length.
        % Ensures last point is not duplicated; returns N vertices (closed implicitly).
        x = x(:); y = y(:);
        % Close explicitly for length computation
        xc = [x; x(1)];
        yc = [y; y(1)];
        ds = hypot(diff(xc), diff(yc));
        s = [0; cumsum(ds)];
        L = s(end);
        if L <= 0
            error('Zero perimeter length.');
        end
        s_query = linspace(0, L*(1 - 1/N), N).'; % N points excluding duplicate end
        xp = interp1(s, xc, s_query, 'linear');
        yp = interp1(s, yc, s_query, 'linear');
        s_c = s_query / L; % nondimensional arc length s/C with C interpreted as perimeter here
    end

    function [xc, yc, S, tx, ty, nx, ny, xc_mid, yc_mid, s_mid] = buildPanels(x, y)
        % Construct panel geometry and normals from ordered vertices.
        % Panels i connect (xi, yi) -> (xi+1, yi+1), with i=1..N; last connects to first.
        x = x(:); y = y(:);
        Np = numel(x);
        % Close by wrapping indices
        x2 = [x(2:end); x(1)];
        y2 = [y(2:end); y(1)];
        dx = x2 - x;
        dy = y2 - y;
        S = hypot(dx, dy); % panel lengths
        tx = dx ./ S; ty = dy ./ S; % unit tangents
        % Outward normal: rotate tangent by +90 deg -> ( -ty, tx ), but need outward.
        % Determine outward via polygon area sign (CCW positive area -> outward normal is ( -ty, tx ))
        area2 = 0.5*sum(x.*y2 - x2.*y); % signed area
        if area2 > 0
            nx = -ty; ny = tx; % CCW ordering -> outward normal
        else
            nx = ty; ny = -tx; % CW ordering -> outward normal
        end
        xc_mid = (x + x2)/2;
        yc_mid = (y + y2)/2;
        % cumulative mid-point arc-length (for s/C plotting)
        s_edge = [0; cumsum(S)];
        s_total = s_edge(end);
        s_mid = (s_edge(1:end-1) + s_edge(2:end)) / 2;
        s_mid = s_mid / s_total;
        xc = x; yc = y;
    end

    function [A, rhs, Vn_inf] = assembleNoPenetrationMatrix(xv, yv, S, nx, ny, xcp, ycp, Uinf, alpha_)
        % Influence of constant-strength source panels on normal velocity at control points.
        % Uses analytical integrals for 2D source panel along straight line.
        % A * sigma = rhs, where rhs = - (V_inf . n)
        Np = numel(S);
        A = zeros(Np, Np);
        % Free-stream normal component at each control point
        Vx = Uinf * cos(alpha_);
        Vy = Uinf * sin(alpha_);
        Vn_inf = Vx * nx + Vy * ny; % at each panel (same size Np)
        rhs = -Vn_inf;
        % Precompute panel local frames
        x2 = [xv(2:end); xv(1)];
        y2 = [yv(2:end); yv(1)];
        tx = (x2 - xv) ./ S;
        ty = (y2 - yv) ./ S;
        % For each control point j
        for j = 1:Np
            % Transform control point into local coordinates of each panel i
            for i = 1:Np
                % Shift to panel i start point
                dx = xcp(j) - xv(i);
                dy = ycp(j) - yv(i);
                % Local coordinates: s axis along panel tangent, n axis along panel normal (outward)
                sij = dx*tx(i) + dy*ty(i);
                nij = dx*(-ty(i)) + dy*(tx(i)); % local "left" normal (rotate +90deg). Matches nx sign if CCW
                % Panel extends from s=0 to s=S(i)
                % Influence coefficients for normal velocity from a unit-strength source panel:
                % Vn = (1/(2*pi)) * [theta2 - theta1], where theta are angles from control point to panel endpoints measured in local frame.
                % Compute angles with atan2
                s1 = 0; s2 = S(i);
                % Endpoints in local coordinates: (s, 0), control at (sij, nij)
                % Vn formula in global normal? We need projection onto outward normal of control point j.
                % Simpler: compute induced velocity vector (u,v) from panel i at control j, then dot with n_j.
                % Induced velocity of constant source panel of strength sigma_i per unit length:
                % Contributions in local frame (Katz & Plotkin):
                % u_local = (sigma/(4*pi)) * log( (r2^2) / (r1^2) )
                % w_local = (sigma/(2*pi)) * (atan2((s2 - sij), nij) - atan2((s1 - sij), nij))
                % where u_local is along +s (tangent), w_local along +n_local (left normal).
                % We'll compute for sigma=1, then rotate to global and dot with n_j.
                r1sq = (s1 - sij)^2 + nij^2;
                r2sq = (s2 - sij)^2 + nij^2;
                if r1sq == 0 || r2sq == 0
                    % Avoid singularity at panel endpoints: use small eps
                    eps2 = 1e-30;
                    if r1sq == 0, r1sq = eps2; end
                    if r2sq == 0, r2sq = eps2; end
                end
                u_loc = (1/(4*pi)) * log(r2sq / r1sq);
                theta2 = atan2((s2 - sij), nij);
                theta1 = atan2((s1 - sij), nij);
                w_loc = (1/(2*pi)) * (theta2 - theta1);
                % Convert local (u_loc along +t_i, w_loc along +n_local_left) to global (x,y)
                % Local left normal vector for panel i is nL = (-ty, tx) which equals outward for CCW ordering.
                ux = u_loc*tx(i) + w_loc*(-ty(i));
                uy = u_loc*ty(i) + w_loc*( tx(i));
                % Project onto outward normal at control point j (nx(j), ny(j))
                A(j,i) = ux*nx(j) + uy*ny(j);
            end
            % Self-panel singularity handled by analytic formulas above; near-coincidence ok.
        end
    end

    function [ut, vt] = inducedVelocityFromSourcesAtPoints(xv, yv, S, xcp, ycp, sigma)
        % Compute induced velocity (u,v) at control points due to all source panels with given strengths.
        Np = numel(S);
        ut = zeros(Np,1);
        vt = zeros(Np,1);
        x2 = [xv(2:end); xv(1)];
        y2 = [yv(2:end); yv(1)];
        tx = (x2 - xv) ./ S;
        ty = (y2 - yv) ./ S;
        for j = 1:Np
            ux = 0; uy = 0;
            for i = 1:Np
                dx = xcp(j) - xv(i);
                dy = ycp(j) - yv(i);
                sij = dx*tx(i) + dy*ty(i);
                nij = dx*(-ty(i)) + dy*( tx(i));
                s1 = 0; s2 = S(i);
                r1sq = (s1 - sij)^2 + nij^2;
                r2sq = (s2 - sij)^2 + nij^2;
                if r1sq == 0 || r2sq == 0
                    eps2 = 1e-30;
                    if r1sq == 0, r1sq = eps2; end
                    if r2sq == 0, r2sq = eps2; end
                end
                u_loc = (1/(4*pi)) * log(r2sq / r1sq);
                theta2 = atan2((s2 - sij), nij);
                theta1 = atan2((s1 - sij), nij);
                w_loc = (1/(2*pi)) * (theta2 - theta1);
                ux = ux + sigma(i)*(u_loc*tx(i) + w_loc*(-ty(i)));
                uy = uy + sigma(i)*(u_loc*ty(i) + w_loc*( tx(i)));
            end
            ut(j) = ux; vt(j) = uy;
        end
    end

    function [Vt, Cp, gamma_net] = tangentialVelocityCp(xv, yv, S, tx, ty, nx, ny, xcp, ycp, Uinf, alpha_, sigma)
        % Compute tangential velocity along surface and Cp, and estimate net circulation.
        Vx = Uinf*cos(alpha_);
        Vy = Uinf*sin(alpha_);
        % Induced velocity from sources
        [u_ind, v_ind] = inducedVelocityFromSourcesAtPoints(xv, yv, S, xcp, ycp, sigma);
        % Total velocity at control points
        u = Vx + u_ind;
        v = Vy + v_ind;
        % Tangential component (aligned with panel tangent)
        Vt = u.*tx + v.*ty;
        Cp = 1 - (Vt./Uinf).^2;
        % Estimate net circulation gamma by integrating tangential velocity around the body:
        % Gamma = -∮ V · dl_normal? For 2D airfoil, circulation equals -∮ V_t ds (sign per conv.)
        % Here take Gamma = -sum(Vt_i * S_i). The sign is chosen so that positive alpha on cylinder gives positive Cl.
        gamma_net = -sum(Vt .* S);
    end

    function [Cl, L] = liftFromCirculation(rho_, Uinf_, gamma_net_)
        L = rho_ * Uinf_ * gamma_net_; % per unit span
        % Nondimensionalize Cl using dynamic pressure and reference chord.
        % Use chord as the max(x)-min(x) of resampled vertices:
        % This function will be called with global xv,yv in scope; compute chord here for safety outside.
        Cl = NaN; % will be set by wrapper after determining chord
    end

% --------------------------
% Main loop: accuracy study
% --------------------------
fprintf('\nRunning panel counts: %s\n', mat2str(Nlist));
results = struct('N',{},'resBC',{},'Cl',{},'L',{},'Gamma',{},'chord',{},'perimeter',{});
prevL = NaN;

figure('Name','Cp distributions'); hold on; grid on;
set(gcf,'Color','w');
colors = lines(numel(Nlist));

for k = 1:numel(Nlist)
    Np = Nlist(k);

    % Resample geometry to Np vertices
    [xv, yv, ~] = resampleClosedPolyline(x_in, y_in, Np);

    % Build panels and control points
    [xv, yv, S, tx, ty, nx, ny, xcp, ycp, s_mid] = buildPanels(xv, yv);

    % Assemble linear system for source strengths
    [A, rhs, Vn_inf] = assembleNoPenetrationMatrix(xv, yv, S, nx, ny, xcp, ycp, U_inf, alpha);

    % Solve for sigma
    % Matrix A can be ill-conditioned for some geometries; use backslash
    sigma = A \ rhs;

    % Compute boundary-condition residual: max |n·V_total| at control points
    % Vn_total = Vn_inf + sum_i A_ji * sigma_i = Vn_inf + A*sigma
    Vn_total = Vn_inf + A*sigma;
    resBC = max(abs(Vn_total));

    % Tangential velocity and Cp
    [Vt, Cp, gamma_net] = tangentialVelocityCp(xv, yv, S, tx, ty, nx, ny, xcp, ycp, U_inf, alpha, sigma);

    % Reference lengths: chord and perimeter
    chord = max(xv) - min(xv);
    perim = sum(S);

    % Lift from circulation
    L = rho * U_inf * gamma_net; % per unit span
    if chord > 0
        Cl = L / (0.5 * rho * U_inf^2 * chord);
    else
        Cl = NaN;
    end

    % Report and store
    results(k).N = Np;
    results(k).resBC = resBC;
    results(k).Cl = Cl;
    results(k).L = L;
    results(k).Gamma = gamma_net;
    results(k).chord = chord;
    results(k).perimeter = perim;

    fprintf('N = %4d | max|BC residual| = %.3e | Gamma = %+ .6e | Cl = %+ .6f\n', Np, resBC, gamma_net, Cl);

    % Write Cp to file: s/C vs Cp
    outName = sprintf('Cp_N%04d.txt', Np);
    T = [s_mid(:), Cp(:)];
    fid = fopen(outName,'w');
    if fid<0
        warning('Could not write %s', outName);
    else
        fprintf(fid, '%% s_over_C    Cp\n');
        fprintf(fid, '%.10f %.10f\n', T.');
        fclose(fid);
    end

    % Plot Cp vs s/C (convention: lower Cp plotted up -> plot -Cp if desired. Here plot Cp)
    plot(s_mid, Cp, '-', 'Color', colors(k,:), 'LineWidth', 1.5, 'DisplayName', sprintf('N=%d', Np));

    % Analytical comparison for circle, if applicable
    if isCircleCase
        % Estimate circle radius as average distance from centroid
        xc0 = mean(xv); yc0 = mean(yv);
        r_est = mean(hypot(xv - xc0, yv - yc0));
        theta = atan2(ycp - yc0, xcp - xc0); % polar angle of control points
        % Potential flow around cylinder at AoA alpha:
        % V_theta/U_inf = -2 sin(theta - alpha)
        Vt_cyl = -2*U_inf*sin(theta - alpha); % tangential velocity (positive in increasing theta)
        Cp_cyl = 1 - (Vt_cyl./U_inf).^2;
        % Overlay as markers on same s/C
        plot(s_mid, Cp_cyl, 'o', 'Color', colors(k,:), 'MarkerSize', 3, 'HandleVisibility','off');
        % Analytical lift per unit span: L = rho * U_inf * Gamma, Gamma = 2*pi*U_inf*R*2*sin(alpha)? Actually Gamma = 2*pi*U_inf*R*2? No.
        % For cylinder at AoA alpha: Gamma = 4*pi*U_inf*R*sin(alpha)
        Gamma_ana = 4*pi*U_inf*r_est*sin(alpha);
        L_ana = rho * U_inf * Gamma_ana;
        if chord > 0
            Cl_ana = L_ana / (0.5*rho*U_inf^2*chord);
            fprintf('   [circle] Analytical Gamma = %.6e | Cl = %.6f (R≈%.4f, chord≈%.4f)\n', Gamma_ana, Cl_ana, r_est, chord);
        else
            fprintf('   [circle] Analytical Gamma = %.6e (R≈%.4f)\n', Gamma_ana, r_est);
        end
    end

    % Experimental comparisons (optional)
    if useExpCp
        % Interpolate exp Cp onto computed s/C range for RMSE
        sE = sExp(:); CpE = CpExp(:);
        % Ensure sE in [0,1]; if not, try to wrap/scale
        sE = mod(sE, 1);
        CpEi = interp1(sE, CpE, s_mid, 'linear', 'extrap');
        rmseCp = sqrt(mean((Cp - CpEi).^2));
        fprintf('   [exp] Cp RMSE vs experimental: %.4f\n', rmseCp);
        % Plot experimental as black markers
        plot(sE, CpE, 'k.', 'MarkerSize', 6, 'DisplayName', 'Exp Cp');
        useExpCp = false; % only plot once
    end
    if useExpCl
        fprintf('   [exp] Cl_exp = %.6f | Cl_num = %.6f | error = %.6f\n', Cl_exp, Cl, Cl - Cl_exp);
        % keep for later iterations too
    end

    % Convergence metric: change in integrated lift vs previous
    if k > 1
        dL = abs(L - prevL);
        fprintf('   Change in L from previous N: %.6e (prev L=%.6e)\n', dL, prevL);
    end
    prevL = L;
end

xlabel('s/C (arc length fraction)');
ylabel('Cp');
title(sprintf('Cp distributions (U_\\infty=%.3g m/s, \\alpha=%.2f deg)', U_inf, alpha_deg));
set(gca, 'YDir','reverse'); % conventional Cp plot
legend('Location','best');

% --------------------------
% Print summary table
% --------------------------
fprintf('\nSummary:\n');
fprintf('   %6s   %14s   %12s   %12s   %12s\n','N','max|BC resid|','Gamma','Lift (N/m)','Cl');
for k = 1:numel(results)
    fprintf('   %6d   %14.3e   %+12.5e   %+12.5e   %+12.6f\n', ...
        results(k).N, results(k).resBC, results(k).Gamma, results(k).L, results(k).Cl);
end

fprintf('\nNotes:\n');
fprintf('- Cp files saved as Cp_Nxxxx.txt (columns: s/C, Cp)\n');
fprintf('- For a pure source-panel method without a Kutta condition, lift on symmetric shapes may be near zero.\n');

function trust_region_rosenbrock_demo
% MATLAB script to:
% 1) Define f(x) = 10(x2 - x1^2)^2 + (1 - x1)^2
% 2) Compute gradient and Hessian of f
% 3) At x=[0;-1] and a=[0;0.5], build quadratic model m_k(p)
% 4) Plot contour lines of m_k(p)
% 5) Solve trust-region subproblem min m_k(p) s.t. ||p|| <= Delta for Delta in [0,2]
% 6) Visualize the family of solutions as Delta varies

% Define f, grad, Hessian
f  = @(x) 10*(x(2) - x(1)^2)^2 + (1 - x(1))^2;
gf = @(x) [ -40*x(1)*(x(2) - x(1)^2) - 2*(1 - x(1));
            20*(x(2) - x(1)^2) ];
Hf = @(x) [ -40*(x(2) - x(1)^2) + 80*x(1)^2 + 2,  -40*x(1);
            -40*x(1),                                 20   ];

% Points
xk1 = [0; -1];
xk2 = [0;  0.5];

% Report gradient and Hessian at specified points
[xk1, g1, H1] = report_point(xk1, gf, Hf);
[xk2, g2, H2] = report_point(xk2, gf, Hf);

% Plot settings
Deltas = linspace(0,2,41);
levels = 30;              % number of contour levels for m_k(p)
prange = 2.5;             % plotting window in p-space

figure('Name','Quadratic model and trust-region solutions at x=[0;-1]');
subplot(1,2,1); hold on; axis equal; box on
plot_quadratic_and_tr_solutions(xk1, f(xk1), g1, H1, Deltas, levels, prange);
title('At x = [0; -1]'); xlabel('p_1'); ylabel('p_2');

figure('Name','Quadratic model and trust-region solutions at a=[0;0.5]');
subplot(1,2,1); hold on; axis equal; box on
plot_quadratic_and_tr_solutions(xk2, f(xk2), g2, H2, Deltas, levels, prange);
title('At a = [0; 0.5]'); xlabel('p_1'); ylabel('p_2');

end

function [xk, gk, Hk] = report_point(xk, gf, Hf)
% Compute and display gradient and Hessian at xk
gk = gf(xk);
Hk = Hf(xk);
fprintf('Point x = [%g; %g]\n', xk(1), xk(2));
fprintf('  grad f(x) = [%g; %g]\n', gk(1), gk(2));
