function plot_quadratic_and_tr_solutions(xk, fk, gk, Hk, Deltas, levels, prange)
% Quadratic model: m_k(p) = f(xk) + gk^T p + 0.5 p^T Hk p

% Grid for contour plot
p1 = linspace(-prange, prange, 201);
p2 = linspace(-prange, prange, 201);
[P1,P2] = meshgrid(p1,p2);
M = zeros(size(P1));
for i = 1:numel(P1)
    p = [P1(i); P2(i)];
    M(i) = fk + gk.'*p + 0.5*p.'*Hk*p;
end

% Contour lines of the quadratic model m_k(p)
contour(P1, P2, M, levels, 'LineColor', [0.6 0.6 0.6]);
colormap(parula); grid on

% Trust-region solutions for varying Delta
psols = zeros(2, numel(Deltas));
for j = 1:numel(Deltas)
    Delta = Deltas(j);
    psols(:,j) = solve_trust_region(gk, Hk, Delta);
end

% Draw trust-region circles and solution path
th = linspace(0, 2*pi, 200);
for j = 1:8:numel(Deltas) % draw a subset of circles for clarity
    Delta = Deltas(j);
    plot(Delta*cos(th), Delta*sin(th), 'Color', [0.8 0.8 1]);
end

% Plot the family of solutions p*(Delta)
plot(psols(1,:), psols(2,:), 'r-', 'LineWidth', 2);
scatter(psols(1,1), psols(2,1), 36, 'filled', 'MarkerFaceColor', 'k'); % Delta=0
scatter(psols(1,end), psols(2,end), 36, 'filled', 'MarkerFaceColor', 'm'); % Delta=max
legend({'m_k contours','TR circles (subset)','p*(\Delta) path','p*(0)','p*(2)'}, 'Location','bestoutside');
end

function p = solve_trust_region(g, H, Delta)
% Solve min 0.5 p^T H p + g^T p s.t. ||p|| <= Delta using Moré-Sorensen/CT method
% If unconstrained minimizer is inside ball, take it; else find lambda >= 0

% Try to solve H p = -g
p_unc = zeros(2,1);
use_unc = false;

% Handle positive definiteness
[Rp,flag] = chol(H);
if flag == 0
    % H is SPD; unconstrained minimizer exists uniquely
    p_unc = - (H \ g);
    if norm(p_unc) <= Delta + 1e-12
        p = p_unc; return;
    end
    % Otherwise, boundary solution with lambda > 0
end

% If H not SPD or p_unc outside TR, solve secular equation for lambda
% We find lambda >= 0 such that ||p(lambda)|| = Delta, where
% p(lambda) = - (H + lambda I)^{-1} g

% Safeguards for lambda search
lamL = 0; 
lamU = 1; 
I = eye(2);

% Increase upper bound until norm(p(lamU)) <= Delta (monotone in lambda for SPD-like regularization)
for k = 1:60
    pU = -((H + lamU*I) \ g);
    if norm(pU) <= Delta
        break;
    end
    lamU = lamU * 2;
end

% Bisection on lambda
for k = 1:80
    lam = 0.5*(lamL + lamU);
    p = -((H + lam*I) \ g);
    if norm(p) > Delta
        lamL = lam;
    else
        lamU = lam;
    end
    if abs(norm(p) - Delta) <= 1e-10
        break;
    end
end

% Final projection to exact radius (numerical tidy)
if norm(p) > 0
    p = p * min(1, Delta / norm(p));
else
    p = p; %#ok<ASGSL>
end
end

Below is a self-contained MATLAB script that:

- Defines the Rosenbrock function f(x), its gradient, and Hessian.
- Evaluates and displays the gradient and Hessian at x = [0; -1] and x = [0; 0.5].
- For each point, builds the quadratic model m_k(p) and visualizes:
  - Contours of m_k(p) on a p-grid centered at the origin
  - Trust-region circles for Δ ∈ linspace(0,2,9)
  - The exact trust-region solutions p*(Δ) (including unconstrained minimizer if inside the ball, and boundary solution via Moré–Sorensen secular equation solved in 1D with a robust bracketed root find)

Copy-paste into a file, e.g., rosenbrock_trust_region_demo.m, and run.

% rosenbrock_trust_region_demo.m
clear; close all; clc;

% Define Rosenbrock function, gradient, Hessian
f  = @(x) (1 - x(1)).^2 + 100*(x(2) - x(1).^2).^2;
grad = @(x) [ -2*(1 - x(1)) - 400*x(1)*(x(2) - x(1)^2);
               200*(x(2) - x(1)^2) ];
hess = @(x) [ 2 - 400*(x(2) - 3*x(1)^2),  -400*x(1);
              -400*x(1),                   200       ];

% Points to analyze
Xk = [0  ,  0;
     -1  ,  0.5]';
labels = {'x = [0; -1]', 'x = [0; 0.5]'};

% Display gradient and Hessian at the two points
for i = 1:2
    xk = Xk(:,i);
    gk = grad(xk);
    Bk = hess(xk);
    fprintf('%s\n', labels{i});
    fprintf('f(x) = %.6f\n', f(xk));
    fprintf('grad f(x) = [%.6f; %.6f]\n', gk(1), gk(2));
    fprintf('Hess f(x) = [%.6f %.6f; %.6f %.6f]\n\n', Bk(1,1),Bk(1,2),Bk(2,1),Bk(2,2));
end

% Trust-region radii
Deltas = linspace(0, 2, 9);

% Visualization and TR solutions for each xk
for i = 1:2
    xk = Xk(:,i);
    gk = grad(xk);
    Bk = hess(xk);

    % Quadratic model m_k(p) = f(xk) + gk' p + 0.5 p' Bk p
    mk = @(p1,p2) f(xk) + gk(1).*p1 + gk(2).*p2 + 0.5*(Bk(1,1)*p1.^2 + 2*Bk(1,2)*p1.*p2 + Bk(2,2)*p2.^2);

    % Grid for plotting m_k contours (centered at origin in p-space)
    pmax = 2.2;
    ngrid = 401;
    p1 = linspace(-pmax, pmax, ngrid);
    p2 = linspace(-pmax, pmax, ngrid);
    [P1,P2] = meshgrid(p1,p2);
    M = mk(P1,P2);

    % Prepare figure
    figure('Color','w'); hold on; axis equal; box on;
    % Contours
    [C,hc] = contour(P1,P2,M, 40, 'LineWidth', 1);
    colormap(parula(64));
    clabel(C,hc,'LabelSpacing',300,'Color',[0.2 0.2 0.2]);

    % Draw trust-region circles
    th = linspace(0, 2*pi, 300);
    for d = 1:numel(Deltas)
        Delta = Deltas(d);
        plot(Delta*cos(th), Delta*sin(th), 'Color', [0.7 0.7 0.7], 'LineWidth', 0.8);
    end

    % Compute and plot trust-region solutions p*(Delta)
    Pstar = zeros(2, numel(Deltas));
    types = strings(1, numel(Deltas)); % 'unconstrained' or 'boundary'
    % Unconstrained minimizer
    [pu, uncon_ok] = try_unconstrained_minimizer(Bk, gk);

    for d = 1:numel(Deltas)
        Delta = Deltas(d);
        if uncon_ok && norm(pu) <= Delta + 1e-12
            pstar = pu; types(d) = "unconstrained";
        else
            % Boundary solution via Moré–Sorensen: solve (B + lambda I) p = -g, ||p||=Delta, lambda>=0
            pstar = trust_region_boundary_solution(Bk, gk, Delta);
            types(d) = "boundary";
        end
        Pstar(:,d) = pstar;
    end

    % Plot optimizer points and path
    plot(Pstar(1,:), Pstar(2,:), 'r-o', 'LineWidth', 1.5, 'MarkerFaceColor','r', 'DisplayName','p*(\Delta)');
    % Mark unconstrained if present
    if uncon_ok
        plot(pu(1), pu(2), 'kp', 'MarkerSize', 10, 'MarkerFaceColor','y', 'DisplayName','unconstrained minimizer');
    end

    % Decorations
    xlabel('p_1'); ylabel('p_2');
    title(sprintf('Quadratic model contours and trust-region solutions at %s', labels{i}));
    legend('Location','bestoutside');
    xlim([-pmax pmax]); ylim([-pmax pmax]);
    grid on;

    % Also overlay colorbar for model values
    colorbar; caxis([min(M(:)) max(M(:))]);
end

% ---- Helper functions (nested or local) ----
function [pu, ok] = try_unconstrained_minimizer(B, g)
% Return unconstrained minimizer pu = -B\g if B is SPD (or at least invertible with positive curvature).
% Check using Cholesky; if fails, declare not OK.
    ok = false;
    pu = [NaN; NaN];
    % Try Cholesky for SPD
    [R, pflag] = chol((B + B')/2); % symmetrize for safety
    if pflag == 0
        pu = - (R \ (R' \ g));
        ok = true;
    else
        % If not SPD, still test invertibility and if stationary point is a minimizer (eigs > 0)
        % For trust-region purposes we require SPD to accept unconstrained point.
        ok = false;
    end
end

function p = trust_region_boundary_solution(B, g, Delta)
% Solve min g'p + 0.5 p' B p s.t. ||p|| = Delta (exact solution on boundary).
% Finds lambda >= 0 such that p(lambda) = -(B + lambda I)^{-1} g and ||p(lambda)|| = Delta.
% Robust 1D root find with bracketing and Newton safeguarded steps.
    B = (B + B')/2; % ensure symmetry
    n = size(B,1);
    I = eye(n);

    % If g == 0, any p on boundary with negative curvature direction is acceptable; take steepest-eigen direction
    if norm(g) == 0
        [V,D] = eig(B);
        [lam_min, idx] = min(diag(D));
        dir = V(:,idx);
        p = Delta * dir / norm(dir);
        return;
    end

    % If B is SPD, we can bracket lambda easily starting from 0
    % General approach: build phi(lambda) = 1/||p(lambda)|| - 1/Delta, seek phi=0
    % We instead solve psi(lambda) = ||p(lambda)|| - Delta = 0
    % Evaluate at lambda = 0; if matrix singular/indefinite or ||p(0)|| < Delta not admissible, increase lambda.
    % Use Cholesky attempts to evaluate p(lambda).
    function [p, ok] = p_of_lambda(lambda)
        A = B + lambda*I;
        [R, pflag] = chol(A);
        if pflag ~= 0
            ok = false; p = [NaN; NaN];
        else
            p = - (R \ (R' \ g));
            ok = true;
        end
    end

    % Bracket lambda
    lambda_lo = 0;
    [p0, ok0] = p_of_lambda(lambda_lo);
    if ok0
        nrm0 = norm(p0);
    else
        nrm0 = Inf; % treat as too large
    end
    % We need ||p|| to decrease with lambda; if nrm0 <= Delta, still must go to boundary (since unconstrained not allowed),
    % so set lower bound as 0 and increase lambda until ||p|| <= Delta to ensure monotonic region.
    lambda_hi = 1;
    maxit_bracket = 60;
    for it = 1:maxit_bracket
        [p_hi, okh] = p_of_lambda(lambda_hi);
        if okh
            if norm(p_hi) <= Delta
                break;
            end
        end
        lambda_hi = lambda_hi * 2;
        if lambda_hi > 1e16
            break;
        end
    end
    % If failed to find hi, fallback to eigen-decomposition and compute exact boundary solution in the subspace
    if lambda_hi > 1e16
        % Use eigen-decomposition approach
        [Q,D] = eig(B);
        lam = diag(D);
        gt = Q' * g;
        % Solve for lambda by scalar equation sum( (gt_i)^2 / (lam_i + lambda)^2 ) = Delta^2
        % Bracket lambda starting from max(0, -min(lam))+eps
        lambda0 = max(0, -min(lam)) + 1e-12;
        % Expand upper bound until LHS <= Delta^2
        lhs = @(lmb) sum( (gt.^2) ./ (lam + lmb).^2 );
        l_lo = lambda0; l_hi = max(1, lambda0*2);
        for it=1:60
            if lhs(l_hi) <= Delta^2
                break;
            end
            l_hi = l_hi*2;
        end
        % Bisection
        for it=1:100
            l_mid = 0.5*(l_lo + l_hi);
            if lhs(l_mid) > Delta^2
                l_lo = l_mid;
            else
                l_hi = l_mid;
            end
            if abs(l_hi - l_lo) <= 1e-12*(1 + l_hi)
                break;
            end
        end
        lambda = 0.5*(l_lo + l_hi);
        coeff = - gt ./ (lam + lambda);
        p = Q * coeff;
        % Project to exact radius
        p = Delta * p / norm(p);
        return;
    end

    % Now we have bracket [lambda_lo, lambda_hi] with ||p(lambda_hi)|| <= Delta
    % Use safeguarded Newton on psi(lambda) = 1/||p|| - 1/Delta or psi = ||p|| - Delta
    psi = @(pp) norm(pp) - Delta;

    lo = lambda_lo; hi = lambda_hi;
    pl, ok_lo = p_of_lambda(lo); if ~ok_lo, pl = [NaN;NaN]; end
    ph, ok_hi = p_of_lambda(hi); % ok_hi should be true
    for it = 1:100
        % Secant-like step using derivative formula: d/dλ p = -A^{-1} p, so d/dλ ||p|| = - (p' A^{-1} p)/||p||
        % Compute mid Newton step if possible
        lambda_try = NaN;
        if ok_hi
            Ahi = B + hi*I;
            % Solve Ahi z = p(hi) for z
            z = Ahi \ ph;
            dpsi = - (ph' * z) / norm(ph);
            if isfinite(dpsi) && dpsi ~= 0
                lambda_newton = hi - psi(ph)/dpsi;
                % Safeguard into (lo, hi)
                lambda_try = min(max(lambda_newton, lo), hi);
            end
        end
        if ~isfinite(lambda_try)
            lambda_try = 0.5*(lo + hi);
        end

        [pt, okt] = p_of_lambda(lambda_try);
        if ~okt
            % Move away from singularity
            lo = lambda_try;
            pl = pt; ok_lo = false;
        else
            if psi(pt) > 0
                % ||p|| > Delta: need larger lambda
                lo = lambda_try; pl = pt; ok_lo = true;
            else
                hi = lambda_try; ph = pt; ok_hi = true;
            end
        end

        if hi - lo <= 1e-12*(1 + hi)
            break;
        end
    end
    % Take hi solution (feasible)
    p = ph;
    % Ensure exactly on boundary numerically
    if norm(p) > 0
        p = Delta * p / norm(p);
    end
end

Notes:
- The trust_region_boundary_solution implements the exact solution p*(Δ) using the Moré–Sorensen condition by solving for the Lagrange multiplier λ with a robust bracketed search and Newton updates. It falls back to an eigen-decomposition-based solver if direct bracketing fails.
- The unconstrained minimizer is used when the Hessian at xk is positive definite and the minimizer lies strictly inside the trust-region ball.

Here’s a concise, hands-on introduction to a toy “query parser” that converts a pre-parsed SQL AST (Abstract Syntax Tree) into a relational algebra (RA) expression tree.

Key ideas:
- We do not parse SQL text. Instead, we start with Python objects that already represent the SQL query (SQL AST).
- We translate that SQL AST into a relational algebra AST using basic operators: Table (base relation), Selection (WHERE), Projection (SELECT), and Product (cross-product for multiple tables).
- We include examples of input SQL strings (for readability), the code that constructs their AST, and the resulting RA expressions.

Code and examples:

```python
your_code_here
from __future__ import annotations
from dataclasses import dataclass
from typing import List, Optional

# ---------- SQL AST (minimal) ----------

class SQLExpr:
    pass

@dataclass
class Column(SQLExpr):
    name: str
    table: Optional[str] = None  # e.g., "users.id" => Column(name="id", table="users")

@dataclass
class Literal(SQLExpr):
    value: object

@dataclass
class Comparison(SQLExpr):
    op: str  # e.g., '=', '<', '>', '<=', '>='
    left: SQLExpr
    right: SQLExpr

@dataclass
class BooleanOp(SQLExpr):
    op: str  # 'AND' or 'OR'
    left: SQLExpr
    right: SQLExpr

@dataclass
class Not(SQLExpr):
    expr: SQLExpr

@dataclass
class SelectItem:
    expr: SQLExpr
    alias: Optional[str] = None

@dataclass
class AllColumns(SQLExpr):
    # Represents SELECT *
    pass

@dataclass
class TableRef:
    name: str
    alias: Optional[str] = None

@dataclass
class SelectStmt:
    select_list: List[SelectItem]         # items in SELECT clause
    from_tables: List[TableRef]           # tables in FROM clause
    where: Optional[SQLExpr] = None       # optional WHERE predicate


# ---------- Relational Algebra AST (minimal) ----------

class RAExpr:
    pass

@dataclass
class RATable(RAExpr):
    name: str
    alias: Optional[str] = None

@dataclass
class RAProduct(RAExpr):
    left: RAExpr
    right: RAExpr

@dataclass
class RASelection(RAExpr):
    predicate: SQLExpr
    child: RAExpr

@dataclass
class RAProjection(RAExpr):
    items: List[SelectItem]  # project expressions (and aliases)
    child: RAExpr


# ---------- Pretty printing helpers ----------

def expr_to_str(e: SQLExpr) -> str:
    if isinstance(e, Column):
        return f"{e.table}.{e.name}" if e.table else e.name
    if isinstance(e, Literal):
        return repr(e.value)
    if isinstance(e, Comparison):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, BooleanOp):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, Not):
        return f"(NOT {expr_to_str(e.expr)})"
    if isinstance(e, AllColumns):
        return "*"
    return f"<expr:{e.__class__.__name__}>"

def ra_to_str(ra: RAExpr, indent: int = 0) -> str:
    pad = "  " * indent
    if isinstance(ra, RATable):
        alias = f" AS {ra.alias}" if ra.alias else ""
        return f"{pad}Table({ra.name}{alias})"
    if isinstance(ra, RAProduct):
        return f"{pad}Product\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RASelection):
        return f"{pad}Select[{expr_to_str(ra.predicate)}]\n{ra_to_str(ra.child, indent+1)}"
    if isinstance(ra, RAProjection):
        items = ", ".join(
            f"{expr_to_str(i.expr)}" + (f" AS {i.alias}" if i.alias else "")
            for i in ra.items
        )
        return f"{pad}Project[{items}]\n{ra_to_str(ra.child, indent+1)}"
    return f"{pad}<RA:{ra.__class__.__name__}>"


# ---------- Translator: SQL AST -> RA AST ----------

class TranslationError(Exception):
    pass

def fold_product(tables: List[TableRef]) -> RAExpr:
    assert len(tables) >= 1
    ra: RAExpr = RATable(tables[0].name, alias=tables[0].alias)
    for tr in tables[1:]:
        ra = RAProduct(left=ra, right=RATable(tr.name, alias=tr.alias))
    return ra

def translate_select(stmt: SelectStmt) -> RAExpr:
    # Basic validation
    if not stmt.from_tables:
        raise TranslationError("Missing FROM clause.")
    if not stmt.select_list:
        raise TranslationError("Empty SELECT list is not allowed.")

    # 1) FROM: single table or multiple tables => Product chain
    if len(stmt.from_tables) == 1:
        ra: RAExpr = RATable(name=stmt.from_tables[0].name, alias=stmt.from_tables[0].alias)
    else:
        ra = fold_product(stmt.from_tables)

    # 2) WHERE: add Selection
    if stmt.where is not None:
        ra = RASelection(predicate=stmt.where, child=ra)

    # 3) SELECT: add Projection, unless it's SELECT *
    only_star = len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
    if only_star:
        return ra
    else:
        return RAProjection(items=stmt.select_list, child=ra)


# ---------- Examples (SQL input and RA output) ----------

if __name__ == "__main__":
    # Example 1
    # SQL: SELECT id, name FROM users WHERE age > 18;
    stmt1 = SelectStmt(
        select_list=[SelectItem(Column("id")), SelectItem(Column("name"))],
        from_tables=[TableRef("users")],
        where=Comparison(">", Column("age"), Literal(18)),
    )
    ra1 = translate_select(stmt1)
    print("Example 1 SQL: SELECT id, name FROM users WHERE age > 18;")
    print(ra_to_str(ra1), end="\n\n")

    # Example 2
    # SQL: SELECT * FROM users;
    stmt2 = SelectStmt(
        select_list=[SelectItem(AllColumns())],
        from_tables=[TableRef("users")],
        where=None,
    )
    ra2 = translate_select(stmt2)
    print("Example 2 SQL: SELECT * FROM users;")
    print(ra_to_str(ra2), end="\n\n")

    # Example 3 (multi-table / implicit join via WHERE)
    # SQL:
    #   SELECT u.id, o.total
    #   FROM users AS u, orders AS o
    #   WHERE u.id = o.user_id AND o.total > 100;
    stmt3 = SelectStmt(
        select_list=[SelectItem(Column("id", table="u")), SelectItem(Column("total", table="o"))],
        from_tables=[TableRef("users", alias="u"), TableRef("orders", alias="o")],
        where=BooleanOp(
            "AND",
            left=Comparison("=", Column("id", "u"), Column("user_id", "o")),
            right=Comparison(">", Column("total", "o"), Literal(100)),
        ),
    )
    ra3 = translate_select(stmt3)
    print("Example 3 SQL: SELECT u.id, o.total FROM users AS u, orders AS o WHERE u.id = o.user_id AND o.total > 100;")
    print(ra_to_str(ra3), end="\n\n")
```

What’s happening:
- FROM builds the base RA subtree (single RATable or left-deep RAProduct).
- WHERE wraps it in RASelection.
- SELECT wraps it in RAProjection unless it’s SELECT *.

Example RA outputs (indicative):
- Example 1:
  Project[id, name]
    Select[(age > 18)]
      Table(users)

- Example 2:
  Table(users)

- Example 3:
  Project[u.id, o.total]
    Select[((u.id = o.user_id) AND (o.total > 100))]
      Product
        Table(users AS u)
        Table(orders AS o)

Below is a pragmatic, high-level plan to port the .NET/SQL lookup to a Nest.js (Express) microservice with an optional MongoDB backend, plus containerization and deployment steps. It starts in in-memory mode (fastest path, no DB) and cleanly upgrades to Mongo when needed—without changing the API.

High-level migration plan

Phase 0 — Discovery and contract
- Inventory current APIs, clients, SLAs, data volume, update cadence, and error semantics.
- Extract or sample the source data (XML or SQL tables) and identify the canonical record shape.
- Define response parity (fields, casing, nulls vs empty arrays) to avoid downstream surprises.

Phase 1 — Prototype in-memory (no DB)
- Build a Nest.js service that:
  - Parses the XML into JSON at startup.
  - Builds in-memory indexes for fast equality lookups on required fields.
  - Exposes endpoints: GET /lookup, GET /lookup/fields, GET /lookup/count, GET /health, POST /lookup/reload.
- Add normalization (lowercase, trim, unicode normalization) so lookups are consistent with the legacy service.
- Add file-watch + atomic index swap for safe reloads.

Exit criteria:
- API parity demonstrated on a golden set.
- P95 latency < 30 ms; readiness/health endpoints added.

Phase 2 — MongoDB option and ETL
- Add a USE_MONGO toggle; when true, read/write from Mongo with indexes on primary and lookup fields.
- Implement one-off ETL(s):
  - XML → Mongo for existing XML pipelines.
  - Optional SQL → Mongo if pulling directly from SQL is preferred during transition.
- Keep response contract identical between in-memory and Mongo modes.

Exit criteria:
- Data seeded in non-prod Mongo; Mongo queries match in-memory responses.
- Indexes validated; P95 latency < 80 ms under expected load.

Phase 3 — Non-functional hardening
- Input validation (allowlist of fields), rate limiting, structured logging, request/response tracing IDs.
- Metrics (requests, latency, heap, reload duration).
