1) In-memory indexer and controller

```python
# src/lookup/indexer.ts
import { XMLParser } from 'fast-xml-parser';

type IndexMap = Map<string, any[]>;
type FieldIndex = Record<string, IndexMap>;

export interface BuildOptions {
  primaryKey: string;
  indexFields: string[];
  recordPath: string; // dot-path into parsed XML
  normalizer?: (v: any) => string;
}
export interface InMemoryStore {
  records: any[];
  byId: Map<string, any>;
  indexes: FieldIndex;
}
const defaultNormalizer = (v: any) =>
  typeof v === 'string' ? v.normalize('NFC').trim().toLowerCase() : String(v);

const getByPath = (obj: any, path: string) =>
  path.split('.').reduce((acc, k) => (acc ? acc[k] : undefined), obj);

export async function buildStoreFromXml(xmlText: string, opts: BuildOptions): Promise<InMemoryStore> {
  const normalizer = opts.normalizer ?? defaultNormalizer;
  const parser = new XMLParser({ ignoreAttributes: false, trimValues: true });
  const parsed = parser.parse(xmlText);
  const arr = getByPath(parsed, opts.recordPath);
  if (!Array.isArray(arr)) throw new Error(`XML_RECORD_PATH not an array: ${opts.recordPath}`);

  const records = arr;
  const byId = new Map<string, any>();
  const indexes: FieldIndex = {};
  const allFields = Array.from(new Set([opts.primaryKey, ...opts.indexFields]));
  for (const f of allFields) indexes[f] = new Map();

  for (const r of records) {
    for (const f of allFields) {
      const raw = r[f];
      if (raw == null) continue;
      const key = normalizer(raw);
      if (f === opts.primaryKey) byId.set(key, r);
      const list = indexes[f].get(key);
      if (list) list.push(r);
      else indexes[f].set(key, [r]);
    }
  }
  return { records, byId, indexes };
}

export function lookup(store: InMemoryStore, field: string, value: string) {
  const map = store.indexes[field];
  if (!map) return [];
  const key = defaultNormalizer(value);
  return map.get(key) || [];
}
```

```python
# src/lookup/lookup.controller.ts
import { Controller, Get, Post, Query, Req, HttpException, HttpStatus } from '@nestjs/common';
import { readFile } from 'node:fs/promises';
import { buildStoreFromXml, lookup, InMemoryStore } from './indexer';

let STORE: InMemoryStore | null = null;
let RELOADING = false;

async function loadStore(): Promise<void> {
  const xml = await readFile(process.env.XML_PATH || '/app/data/records.xml', 'utf-8');
  STORE = await buildStoreFromXml(xml, {
    primaryKey: process.env.PRIMARY_KEY_FIELD || 'id',
    indexFields: (process.env.LOOKUP_INDEX_FIELDS || 'code').split(',').map(s => s.trim()).filter(Boolean),
    recordPath: process.env.XML_RECORD_PATH || 'records.record'
  });
}

@Controller('lookup')
export class LookupController {
  constructor() { if (!STORE) loadStore().catch(console.error); }

  @Get()
  async get(@Query('field') field: string, @Query('value') value: string) {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    if (!field || value == null) throw new HttpException('field and value required', HttpStatus.BAD_REQUEST);
    if (!STORE.indexes[field]) throw new HttpException('Unknown field', HttpStatus.BAD_REQUEST);
    return lookup(STORE, field, value);
  }

  @Get('fields')
  fields() {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    return { fields: Object.keys(STORE.indexes) };
  }

  @Get('count')
  count() {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    return { count: STORE.records.length };
  }

  @Post('reload')
  async reload(@Req() req) {
    const token = req.headers['x-admin-token'];
    if (token !== (process.env.RELOAD_TOKEN || 'change-me')) {
      throw new HttpException('Forbidden', HttpStatus.FORBIDDEN);
    }
    if (RELOADING) return { status: 'already_reloading' };
    RELOADING = true;
    try {
      await loadStore();
      return { status: 'ok' };
    } finally {
      RELOADING = false;
    }
  }
}
```

