import { Controller, Get, Query, HttpException, HttpStatus } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';

@Controller('lookup')
export class LookupMongoController {
  constructor(@InjectModel('Record') private readonly rec: Model<any>) {}

  @Get()
  async get(@Query('field') field: string, @Query('value') value: string) {
    if (!field || value == null) throw new HttpException('field and value required', HttpStatus.BAD_REQUEST);
    const allowed = new Set([process.env.PRIMARY_KEY_FIELD || 'id', ...(process.env.LOOKUP_INDEX_FIELDS || 'code').split(',').map(s => s.trim())]);
