    return this.rec.find({ [field]: value }).limit(100).lean();
  }

  @Get('count')
  async count() { return { count: await this.rec.estimatedDocumentCount() }; }

  @Get('fields')
  fields() {
    return { fields: [process.env.PRIMARY_KEY_FIELD || 'id', ...(process.env.LOOKUP_INDEX_FIELDS || 'code').split(',').map(s => s.trim())] };
  }
}
