3) ETL utilities (one-off)

- XML to Mongo

```python
# tools/xml_to_mongo.ts
import { XMLParser } from 'fast-xml-parser';
import { MongoClient } from 'mongodb';
import { readFile } from 'node:fs/promises';

async function main() {
  const uri = process.env.MONGO_URI!;
  const db = process.env.MONGO_DB || 'lookupdb';
  const col = process.env.MONGO_COLLECTION || 'records';
  const pk = process.env.PRIMARY_KEY_FIELD || 'id';
  const xmlPath = process.env.XML_PATH || './data/records.xml';
  const recordPath = process.env.XML_RECORD_PATH || 'records.record';

  const xml = await readFile(xmlPath, 'utf-8');
  const parser = new XMLParser({ ignoreAttributes: false, trimValues: true });
  const parsed = parser.parse(xml);
  const records = recordPath.split('.').reduce((a, k) => (a ? a[k] : undefined), parsed);
  if (!Array.isArray(records)) throw new Error('recordPath did not resolve to array');

  const client = new MongoClient(uri);
  await client.connect();
  const coll = client.db(db).collection(col);

  const ops = records.map((r: any) =>
    r[pk] != null
      ? ({ updateOne: { filter: { [pk]: r[pk] }, update: { $set: r }, upsert: true } })
      : ({ insertOne: { document: r } })
  );
  if (ops.length) await coll.bulkWrite(ops, { ordered: false });

  await client.close();
  console.log(`Loaded ${records.length} records into ${db}.${col}`);
}
main().catch(e => { console.error(e); process.exit(1); });
```

