  const dbName = process.env.MONGO_DB || 'lookupdb';
  const colName = process.env.MONGO_COLLECTION || 'records';
  const pk = process.env.PRIMARY_KEY_FIELD || 'id';
  const xmlPath = process.env.XML_PATH || './data/records.xml';
  const recordPath = process.env.XML_RECORD_PATH || 'records.record';

