  const parser = new XMLParser({ ignoreAttributes: false, trimValues: true });
  const parsed = parser.parse(xml);
  const records = recordPath.split('.').reduce((a, k) => (a ? a[k] : undefined), parsed);
  if (!Array.isArray(records)) throw new Error('recordPath did not resolve to array');

  const client = new MongoClient(uri);
  await client.connect();
  const col = client.db(dbName).collection(colName);

  const ops = records.map((r: any) =>
    r[pk] != null
      ? ({ updateOne: { filter: { [pk]: r[pk] }, update: { $set: r }, upsert: true } })
      : ({ insertOne: { document: r } })
  );
  if (ops.length) await col.bulkWrite(ops, { ordered: false });

  await client.close();
  console.log(`Loaded ${records.length} records into ${dbName}.${colName}`);
}

main().catch(err => { console.error(err); process.exit(1); });
