const CONTROL_SOCKET: &str = "/run/sysx.sock";
const LOG_DIR: &str = "/var/log/sysx";

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

impl FromStr for RestartPolicy {
    type Err = anyhow::Error;
    fn from_str(s: &str) -> Result<Self> {
        Ok(match s {
            "never" => RestartPolicy::Never,
            "on-failure" => RestartPolicy::OnFailure,
            "always" => RestartPolicy::Always,
            _ => anyhow::bail!("invalid restart policy"),
        })
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
    // Optional working dir or env can be added if needed
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
enum TaskState {
    Stopped,
    Running,
    Exited(i32), // exit code or signal encoded as negative
    Failed(i32),
}

#[derive(Clone, Debug, Serialize, Deserialize)]
struct TaskStatus {
    name: String,
    pid: Option<i32>,
    state: TaskState,
    restart: RestartPolicy,
    last_start: Option<u64>,
    last_exit: Option<u64>,
    log_path: String,
}

struct TaskRuntime {
    spec: TaskSpec,
    pid: Option<Pid>,
    state: TaskState,
    last_start: Option<Instant>,
    last_exit: Option<Instant>,
    log_path: PathBuf,
}

impl TaskRuntime {
    fn status(&self) -> TaskStatus {
        TaskStatus {
            name: self.spec.name.clone(),
            pid: self.pid.map(|p| p.as_raw()),
            state: self.state.clone(),
            restart: self.spec.restart,
            last_start: self
                .last_start
                .map(|t| t.elapsed().as_millis() as u64)
                .map(|e| e), // elapsed, not absolute; good enough for demo
            last_exit: self
                .last_exit
                .map(|t| t.elapsed().as_millis() as u64)
                .map(|e| e),
            log_path: self.log_path.to_string_lossy().into_owned(),
        }
    }
}

#[derive(Serialize, Deserialize, Debug)]
