}

fn is_pid1() -> bool {
    unsafe { libc::getpid() == 1 }
}

// Utility to run a command and ignore errors (logging to stderr)
fn run_cmd(mut argv: Vec<&str>) -> i32 {
    if argv.is_empty() {
        return -1;
    }
    let prog = argv.remove(0);
    match Command::new(prog).args(argv.clone()).status() {
        Ok(s) => s.code().unwrap_or(-1),
        Err(e) => {
            eprintln!("sysx: failed to exec {} {:?}: {}", prog, argv, e);
            -1
        }
    }
}

// Minimal mount helper
fn ensure_mount(src: Option<&str>, target: &str, fstype: &str, flags: MsFlags, data: Option<&str>) -> Result<()> {
    if !Path::new(target).exists() {
        fs::create_dir_all(target).ok();
    }
    let res = mount(
        src.map(|s| CString::new(s).unwrap()).as_ref(),
        &CString::new(target).unwrap(),
        Some(&CString::new(fstype).unwrap()),
        flags,
        data.map(|d| CString::new(d).unwrap()).as_ref(),
    );
    match res {
        Ok(_) => Ok(()),
        Err(nix::Error::Sys(Errno::EBUSY)) => Ok(()), // already mounted
        Err(e) => Err(anyhow::anyhow!("mount {} on {} type {} failed: {}", src.unwrap_or("none"), target, fstype, e)),
    }
}

fn remount_root_rw() {
    let _ = mount::<str, str, str, str>(
        None, "/", None, MsFlags::MS_REMOUNT, None
    );
}

fn set_signal_handlers() -> Result<()> {
    unsafe {
        let sa_chld = SigAction::new(
            SigHandler::Handler(sigchld_handler),
            SaFlags::SA_NOCLDSTOP | SaFlags::SA_RESTART,
            SigSet::empty(),
        );
        signal::sigaction(Signal::SIGCHLD, &sa_chld)?;
        let sa_ign = SigAction::new(SigHandler::SigIgn, SaFlags::SA_RESTART, SigSet::empty());
        signal::sigaction(Signal::SIGHUP, &sa_ign)?;
        signal::sigaction(Signal::SIGINT, &sa_ign)?;
        signal::sigaction(Signal::SIGTERM, &sa_ign)?;
    }
    Ok(())
}

static mut SIGCHLD_FLAG: bool = false;
extern "C" fn sigchld_handler(_sig: i32) {
    unsafe { SIGCHLD_FLAG = true; }
}

// Reap all zombies
fn reap_zombies(task_table: &mut HashMap<String, TaskRuntime>) {
    loop {
        match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
            Ok(WaitStatus::Exited(pid, code)) => {
                for (_k, t) in task_table.iter_mut() {
                    if t.pid == Some(pid) {
                        t.state = if code == 0 { TaskState::Exited(code) } else { TaskState::Failed(code) };
                        t.pid = None;
                        t.last_exit = Some(Instant::now());
                    }
                }
            }
            Ok(WaitStatus::Signaled(pid, sig, _coredump)) => {
                for (_k, t) in task_table.iter_mut() {
                    if t.pid == Some(pid) {
                        t.state = TaskState::Failed(-(sig as i32));
                        t.pid = None;
                        t.last_exit = Some(Instant::now());
                    }
                }
            }
            Ok(WaitStatus::StillAlive) => break,
            Ok(_) => continue,
            Err(nix::Error::Sys(Errno::ECHILD)) => break,
            Err(e) => {
                eprintln!("sysx: waitpid error: {}", e);
                break;
            }
        }
    }
}

// Start a supervised task with stdout/stderr redirected to log file
fn start_task(task: &mut TaskRuntime) -> Result<()> {
    if task.pid.is_some() {
        return Ok(());
    }
    fs::create_dir_all(LOG_DIR).ok();
    let log_path = &task.log_path;
    let log = OpenOptions::new().create(true).write(true).append(true).open(log_path)
        .with_context(|| format!("open log {}", log_path.display()))?;
    let log_fd = log.as_raw_fd();

    match unsafe { fork() }? {
        ForkResult::Parent { child } => {
            task.pid = Some(child);
            task.state = TaskState::Running;
            task.last_start = Some(Instant::now());
            Ok(())
        }
        ForkResult::Child => {
            // Child: setsid and redirect stdio
            let _ = setsid();
            unsafe {
                dup2(log_fd, 1);
                dup2(log_fd, 2);
            }
            // Close all fds except stdio
            for fd in 3..1024 {
                unsafe { libc::close(fd); }
            }
            // Exec
            if task.spec.cmd.is_empty() {
                eprintln!("empty command for {}", task.spec.name);
                std::process::exit(127);
            }
            let argv_c: Vec<CString> = task.spec.cmd.iter().map(|s| CString::new(s.as_str()).unwrap()).collect();
            let prog = argv_c[0].clone();
            if let Err(e) = execvp(&prog, &argv_c) {
                eprintln!("exec failed: {}: {}", task.spec.cmd[0], e);
                std::process::exit(127);
            }
            unreachable!()
        }
    }
}

// Stop a task (SIGTERM then SIGKILL after grace)
fn stop_task(task: &mut TaskRuntime) -> Result<()> {
    if let Some(pid) = task.pid {
        let _ = signal::kill(pid, Signal::SIGTERM);
        // Wait a bit
        let deadline = Instant::now() + Duration::from_millis(1500);
        loop {
            reap_zombies_dummy(); // make sure if it exited we catch it after returning to main loop
            if Instant::now() > deadline {
                break;
            }
            std::thread::sleep(Duration::from_millis(50));
        }
        // If still running, SIGKILL
        if task.pid.is_some() {
            let _ = signal::kill(pid, Signal::SIGKILL);
        }
    }
    Ok(())
}

fn reap_zombies_dummy() {
    // called outside main loop—non-critical; kernel will deliver SIGCHLD eventually.
    let _ = waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG));
}

// Decide if we should restart a task based on previous state and policy
fn maybe_restart_task(task: &mut TaskRuntime) -> bool {
    match task.spec.restart {
        RestartPolicy::Never => false,
        RestartPolicy::Always => true,
        RestartPolicy::OnFailure => matches!(task.state, TaskState::Failed(_)),
    }
}

// Hardcoded tasks:
// - getty@tty1: agetty -L 115200 tty1
// - dhcp: udhcpc -i eth0
// - sleep10: /bin/sh -c 'sleep 10'
fn default_tasks() -> Vec<TaskSpec> {
    vec![
        TaskSpec {
            name: "getty@tty1".into(),
            // Adjust getty path/baud/tty here if needed:
            cmd: vec!["/sbin/agetty".into(), "-L".into(), "115200".into(), "tty1".into()],
            restart: RestartPolicy::Always,
        },
        TaskSpec {
            name: "dhcp".into(),
            // Adjust interface name here (default eth0) and udhcpc flags
            cmd: vec!["/sbin/udhcpc".into(), "-f".into(), "-i".into(), "eth0".into()],
            restart: RestartPolicy::OnFailure,
        },
        TaskSpec {
            name: "sleep10".into(),
            cmd: vec!["/bin/sh".into(), "-c".into(), "sleep 10".into()],
            restart: RestartPolicy::OnFailure,
        },
    ]
}

fn check_udhcpc_present() -> bool {
    Path::new("/sbin/udhcpc").exists() || Path::new("/bin/udhcpc").exists()
}

fn setup_filesystems() {
    // Sane umask
    unsafe { libc::umask(0o022); }

    // Optional hostname
    let _ = sethostname("devuan-sysx".as_bytes());

    // Ensure /run exists
    fs::create_dir_all("/run").ok();
    fs::create_dir_all("/run").ok();

    // Mount pseudo filesystems
    let _ = ensure_mount(None, "/proc", "proc", MsFlags::empty(), None);
    let _ = ensure_mount(None, "/sys", "sysfs", MsFlags::empty(), None);
    // devtmpfs on /dev
    let _ = ensure_mount(None, "/dev", "devtmpfs", MsFlags::empty(), Some("mode=0755"));
    // pts and shm
    fs::create_dir_all("/dev/pts").ok();
    fs::create_dir_all("/dev/shm").ok();
    let _ = ensure_mount(None, "/dev/pts", "devpts", MsFlags::empty(), Some("mode=0620,ptmxmode=0666,gid=5"));
    let _ = ensure_mount(None, "/dev/shm", "tmpfs", MsFlags::empty(), Some("mode=1777"));

    // Remount root rw if needed
    remount_root_rw();

    // Filesystem checks before mount -a
    // fsck -A -T -C -a: safe auto repair; on fatal error, drop to single user shell.
    let fsck_code = run_cmd(vec!["/sbin/fsck", "-ATCa"]);
    // According to fsck conventions:
    // 0=clean, 1=corrected, 2=reboot needed, 4=errors left uncorrected, 8=operational error, 16=usage, 32=cancelled
    if fsck_code & 0x0C != 0 {
        eprintln!("sysx: fsck reported fatal (code {}), dropping to single-user shell.", fsck_code);
        single_user_shell();
    }

    // Mount all filesystems
    let _ = run_cmd(vec!["/bin/mount", "-a"]);
    // Enable swap
    let _ = run_cmd(vec!["/sbin/swapon", "-a"]);
}

fn single_user_shell() -> ! {
    eprintln!("Entering single-user shell. Type exit to continue (or reboot).");
    loop {
        // Minimal shell
        let status = Command::new("/bin/sh").arg("-l").status();
        eprintln!("shell exited: {:?}", status);
        // after exit, continue boot anyway
        break;
    }
    // Return to boot
    // If you want to stay in shell forever on error, replace with loop {}
    // Continue
    // just proceed
    // not ! anymore
    // But function signature said never; adapt:
    std::process::exit(0);
}

fn bring_up_loopback() {
    // Try: ip link set lo up; ip addr add 127.0.0.1/8 dev lo
    let _ = run_cmd(vec!["/sbin/ip", "link", "set", "lo", "up"]);
    let _ = run_cmd(vec!["/sbin/ip", "addr", "add", "127.0.0.1/8", "dev", "lo"]);
}

fn bring_up_dhcp_if_missing_warn() {
    if !check_udhcpc_present() {
        eprintln!("sysx: udhcpc not found; networking DHCP step skipped.");
    } // The dhcp task may still fail/restart, that’s okay.
}

fn remove_stale_socket() {
    let p = Path::new(CONTROL_SOCKET);
    if p.exists() {
        let _ = fs::remove_file(p);
    }
    // Ensure /run perms
    let _ = fs::create_dir_all("/run");
}

fn serve_control_socket(listener: &UnixListener, task_table: &mut HashMap<String, TaskRuntime>) {
    listener.set_nonblocking(true).ok();
    loop {
        // Accept non-blocking
        match listener.accept() {
            Ok((mut stream, _addr)) => {
                let mut buf = String::new();
                if let Ok(_) = BufReader::new(stream.try_clone().unwrap()).read_line(&mut buf) {
                    if let Ok(msg) = serde_json::from_str::<ControlMsg>(&buf) {
                        let resp = handle_control_msg(msg, task_table);
                        let _ = writeln!(stream, "{}", serde_json::to_string(&resp).unwrap());
                    } else {
                        let _ = writeln!(stream, "{}", serde_json::to_string(&ControlResp::Error("bad json".into())).unwrap());
                    }
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
            Err(e) => {
                eprintln!("sysx: control accept error: {}", e);
                break;
            }
        }
    }
}

fn handle_control_msg(msg: ControlMsg, task_table: &mut HashMap<String, TaskRuntime>) -> ControlResp {
    match msg {
        ControlMsg::List => {
            let list: Vec<TaskStatus> = task_table.values().map(|t| t.status()).collect();
            ControlResp::Ok(json!(list))
        }
        ControlMsg::Start { name } => {
            match task_table.get_mut(&name) {
                Some(t) => {
                    if t.pid.is_none() {
                        if let Err(e) = start_task(t) {
                            return ControlResp::Error(format!("start failed: {}", e));
                        }
                    }
                    ControlResp::Ok(json!(t.status()))
                }
                None => ControlResp::Error("unknown task".into()),
            }
        }
        ControlMsg::Stop { name } => {
            match task_table.get_mut(&name) {
                Some(t) => {
                    if let Err(e) = stop_task(t) {
                        return ControlResp::Error(format!("stop failed: {}", e));
                    }
                    ControlResp::Ok(json!(t.status()))
                }
                None => ControlResp::Error("unknown task".into()),
            }
        }
        ControlMsg::Restart { name } => {
            match task_table.get_mut(&name) {
                Some(t) => {
                    let _ = stop_task(t);
                    if let Err(e) = start_task(t) {
                        return ControlResp::Error(format!("restart failed: {}", e));
                    }
                    ControlResp::Ok(json!(t.status()))
                }
                None => ControlResp::Error("unknown task".into()),
            }
        }
        ControlMsg::TailLog { name, n } => {
            match task_table.get(&name) {
                Some(t) => {
                    let path = &t.log_path;
                    match tail_last_n_lines(path, n) {
                        Ok(lines) => ControlResp::Ok(json!(lines)),
                        Err(e) => ControlResp::Error(format!("tail failed: {}", e)),
                    }
                }
                None => ControlResp::Error("unknown task".into()),
            }
        }
    }
}

fn tail_last_n_lines(path: &Path, n: usize) -> Result<Vec<String>> {
    let f = File::open(path)?;
    let mut reader = BufReader::new(f);
    // Simple method: read all lines and take last n (fine for small logs; no rotation required)
    let mut lines = Vec::new();
    let mut line = String::new();
    loop {
        line.clear();
        let bytes = reader.read_line(&mut line)?;
        if bytes == 0 { break; }
        if line.ends_with('\n') { line.pop(); if line.ends_with('\r') { line.pop(); } }
        lines.push(line.clone());
    }
    let start = if n >= lines.len() { 0 } else { lines.len() - n };
    Ok(lines[start..].to_vec())
}

fn init_main() -> Result<()> {
    eprintln!("sysx: starting as PID 1");

    set_signal_handlers()?;
    setup_filesystems();
    bring_up_loopback();
    bring_up_dhcp_if_missing_warn();

    // Prepare task table
    let mut task_table: HashMap<String, TaskRuntime> = HashMap::new();
    for spec in default_tasks() {
        let log_path = PathBuf::from(format!("{}/{}.log", LOG_DIR, spec.name));
        task_table.insert(
            spec.name.clone(),
            TaskRuntime {
                spec,
                pid: None,
                state: TaskState::Stopped,
                last_start: None,
                last_exit: None,
                log_path,
            },
        );
    }

    // Start tasks marked to run initially: we’ll start all defined tasks; user can stop via CLI.
    // Note: dhcp task may fail if udhcpc missing; it will be in Failed state; restart on-failure policy applies.
    for (_, t) in task_table.iter_mut() {
        let _ = start_task(t);
    }

    // Control socket
    remove_stale_socket();
    let listener = UnixListener::bind(CONTROL_SOCKET).context("bind control socket")?;
    // Make socket world-accessible but writable only by root if desired
    let mut perms = fs::metadata(CONTROL_SOCKET)?.permissions();
    perms.set_mode(0o666);
    fs::set_permissions(CONTROL_SOCKET, perms).ok();

    // Main event loop
    loop {
        // Serve any control requests
        serve_control_socket(&listener, &mut task_table);

        // Reap zombies if SIGCHLD fired
        let need_reap = unsafe { SIGCHLD_FLAG };
        if need_reap {
            unsafe { SIGCHLD_FLAG = false; }
            reap_zombies(&mut task_table);

            // Restart policy enforcement
            for (_k, t) in task_table.iter_mut() {
                if t.pid.is_none() {
                    if maybe_restart_task(t) {
                        // small backoff to avoid spin if it fails instantly
                        if let Some(last_exit) = t.last_exit {
                            if last_exit.elapsed() < Duration::from_secs(1) {
                                continue;
                            }
                        }
                        let _ = start_task(t);
                    }
                }
            }
        }

        // Sleep a bit; simple poll
        std::thread::sleep(Duration::from_millis(200));
    }
}

// Client side: connect to /run/sysx.sock and send one JSON line
fn client_send(msg: &ControlMsg) -> Result<ControlResp> {
    let mut stream = UnixStream::connect(CONTROL_SOCKET)
        .with_context(|| format!("connect to {}", CONTROL_SOCKET))?;
    let line = serde_json::to_string(msg)?;
    writeln!(stream, "{line}")?;
    let mut resp = String::new();
    BufReader::new(stream).read_line(&mut resp)?;
    let parsed: ControlResp = serde_json::from_str(&resp)?;
    Ok(parsed)
}

fn print_resp(resp: ControlResp) -> i32 {
    match resp {
        ControlResp::Ok(v) => {
            println!("{}", serde_json::to_string_pretty(&v).unwrap());
            0
        }
        ControlResp::Error(e) => {
            eprintln!("error: {}", e);
            1
        }
    }
}

fn main() -> Result<()> {
    // If run as pid1 or with subcommand hidden init, run init_main
    let args: Vec<String> = std::env::args().collect();
    let exe_name = Path::new(&args.get(0).cloned().unwrap_or_default())
        .file_name().and_then(|s| s.to_str()).unwrap_or("");
    if is_pid1() || exe_name == "init" || (args.len() > 1 && args[1] == "init-internal") {
        return init_main();
    }

    let cli = Cli::parse();
    match cli.command {
        Some(Commands::List) => {
            let code = print_resp(client_send(&ControlMsg::List)?);
            std::process::exit(code);
        }
        Some(Commands::Start { task }) => {
            let code = print_resp(client_send(&ControlMsg::Start { name: task })?);
            std::process::exit(code);
        }
        Some(Commands::Stop { task }) => {
            let code = print_resp(client_send(&ControlMsg::Stop { name: task })?);
            std::process::exit(code);
        }
        Some(Commands::Restart { task }) => {
            let code = print_resp(client_send(&ControlMsg::Restart { name: task })?);
            std::process::exit(code);
        }
        Some(Commands::TailLog { task, n }) => {
            let code = print_resp(client_send(&ControlMsg::TailLog { name: task, n })?);
            std::process::exit(code);
        }
        Some(Commands::Init) => {
            return init_main();
        }
        None => {
            // default to list
            let code = print_resp(client_send(&ControlMsg::List)?);
            std::process::exit(code);
        }
    }
}

3) Example hardcoded tasks included:
- getty@tty1: agetty -L 115200 tty1, restart=always
- dhcp: udhcpc -i eth0, restart=on-failure
- sleep10: /bin/sh -c "sleep 10", restart=on-failure

Adjustments:
- Change interface name in default_tasks() for udhcpc (e.g., eth0 -> enp0s3).
- Change getty path/args in default_tasks() (e.g., /bin/busybox getty).
- Restart policy logic is enforced in maybe_restart_task() and applied after SIGCHLD reaping.

4) Build and install instructions

- Build dynamically (glibc):
  cargo build --release

- Build static with musl (recommended):
  rustup target add x86_64-unknown-linux-musl
  cargo build --release --target x86_64-unknown-linux-musl

- Install as /sbin/init (be careful; do this in a test VM or chroot):
  sudo cp target/x86_64-unknown-linux-musl/release/sysx /sbin/init
  sudo chmod 0755 /sbin/init

- Symlink CLI for user space:
  sudo ln -s /sbin/init /usr/bin/sysx

- No /etc/inittab is needed; tasks are hardcoded in default_tasks().

- Kernel command line should point to this init if not replacing system init:
  append to kernel cmdline: init=/sbin/init

Usage after boot:
- List tasks: sysx list
- Start task: sysx start getty@tty1
- Stop task: sysx stop dhcp
- Restart task: sysx restart sleep10
- Tail logs: sysx tail-log getty@tty1 50

Implementation notes:
- PID 1 duties: sets umask, signal handlers, zombie reaping, mounts proc/sys/dev/devpts/shm, remounts root rw.
- Filesystems: runs fsck -ATCa, then mount -a, then swapon -a. On fatal fsck errors it gives a single-user shell then proceeds.
- Networking: brings up lo; DHCP via udhcpc task; if udhcpc binary is missing, a warning is printed and the task will fail accordingly.
- Control protocol: one JSON line per request/response over /run/sysx.sock. Example:
  echo '{"cmd":"List"}' | socat - UNIX-CONNECT:/run/sysx.sock

Caveats:
- No log rotation; logs grow indefinitely.
- No dependency ordering beyond hardcoded start.
- No tty management besides getty@tty1.
- Minimal error handling; suitable for small appliances/testing.

Below is a complete, runnable Flask app that renders a compact /embed UI for pasting recipe text or uploading .txt/.pdf files. It validates inputs server-side (type and size), extracts ingredients, performs public lookups (Wikipedia/Wikidata/Datamuse) with timeouts and error handling, generates a whimsical “spell,” and displays clear success/error pages.

How to embed on Square:
- Deploy this app to a public URL (e.g., https://your-spell-app.example.com)
- In Square Online > Website > Edit site > Add section > Embed code, paste this exact snippet (replace the domain with yours):
  <iframe src="https://your-spell-app.example.com/embed" width="100%" height="960" style="border:0;max-width:100%"></iframe>

```python
# app.py
import io
import os
import re
import html
import random
import logging
from typing import List, Dict, Optional

from flask import Flask, request, redirect, url_for, make_response
import requests

# Optional PDF support
try:
    import PyPDF2
    HAS_PDF = True
except Exception:
    HAS_PDF = False

app = Flask(__name__)
# 2 MB upload limit (keeps widget snappy inside an iframe)
app.config["MAX_CONTENT_LENGTH"] = 2 * 1024 * 1024

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("spell-app")

# --------- Ingredient Parsing ---------

UNITS = {
    "cup", "cups", "tsp", "teaspoon", "teaspoons", "tbsp", "tablespoon", "tablespoons",
    "g", "gram", "grams", "kg", "kilogram", "kilograms", "ml", "l", "liter", "liters",
    "oz", "ounce", "ounces", "lb", "pound", "pounds",
    "pinch", "dash", "slice", "slices", "clove", "cloves", "piece", "pieces",
    "can", "cans", "package", "packages", "pkg", "small", "medium", "large"
}
STOPWORDS = {
    "fresh", "dried", "ground", "minced", "chopped", "sliced", "grated", "crushed",
    "to", "taste", "and", "or", "optional", "about", "of"
}
SECTION_BREAKERS = {
    "ingredients", "instructions", "method", "directions", "steps", "preparation",
    "prep", "cook", "cooking", "baking", "notes", "equipment"
}
USER_AGENT = {"User-Agent": "SpellWidget/1.0 (+https://example.com)"}  # Replace with your domain
HTTP_TIMEOUT = 4.0


def normalize_ingredient_line(line: str) -> Optional[str]:
    # Remove parenthetical notes
    line = re.sub(r"\([^)]*\)", "", line)
    # Normalize and trim bullets
    line = line.strip().lstrip("-•*").strip()
    # Remove leading quantities like "1 1/2", "2", "2-3", "200 g"
    line = re.sub(r"^\s*(\d+([\/\.\-]\d+)?(\s+\d+\/\d+)?\s*)+", "", line)
    # Remove unicode fractions like "½"
    line = re.sub(r"^[¼½¾⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞]+\s*", "", line)

    tokens = [t for t in re.split(r"[,\s]+", line) if t]
    if not tokens:
        return None

    # Skip initial unit tokens
    i = 0
    while i < len(tokens) and tokens[i].lower() in UNITS:
        i += 1
    cleaned = tokens[i:] if i < len(tokens) else []

    if not cleaned:
        return None

    # Remove stopwords
    cleaned = [t for t in cleaned if t.lower() not in STOPWORDS]

    if cleaned and cleaned[0].lower() == "of":
        cleaned = cleaned[1:]

    ing = " ".join(cleaned)
    ing = ing.strip(" ,.;:-").strip()

    pieces = ing.split()
    if len(pieces) > 5:
        # Keep likely core, e.g., "brown sugar"
        ing = " ".join(pieces[-3:])

    ing = re.sub(r"\s+", " ", ing).strip().lower()

    if not ing or len(ing) < 2:
        return None

    # Exclude section headers and non-ingredient lines
    if any(h in ing for h in SECTION_BREAKERS):
        return None
    if ing.startswith(("serves", "yield", "time", "total time", "prep time", "cook time")):
        return None
    # Avoid lines that are likely headings with non-alpha characters
    if len(ing.split()) <= 1 and not ing.isalpha():
        return None

    # Trim trailing descriptors like "to taste" or "as needed"
    ing = re.sub(r"\b(to taste|as needed)\b", "", ing).strip()
    return ing if ing else None


def extract_ingredients_from_text(text: str, limit: int = 12) -> List[str]:
    lines = [l.strip() for l in text.splitlines()]
    ingredients_block: List[str] = []
    in_ing = False
    found_section = False

    # Try to find an "Ingredients" section
    for line in lines:
        low = line.strip().lower()
        if not in_ing and re.match(r"^\s*ingredients\s*:?\s*$", low):
            in_ing = True
            found_section = True
            continue
        if in_ing:
            if (
                not line
                or any(b in low for b in SECTION_BREAKERS if b != "ingredients")
                or re.match(r"^\s*[A-Za-z ]{3,}\s*:?\s*$", low)
            ):
                # End on blank or another section header
                if ingredients_block:
                    break
                else:
                    in_ing = False
                    continue
            ingredients_block.append(line)

    candidates: List[str] = []
    if found_section and ingredients_block:
        for raw in ingredients_block:
            ing = normalize_ingredient_line(raw)
            if ing:
                candidates.append(ing)
    else:
        # Fallback: scan all lines, prefer bullets or lines with quantities
        for raw in lines:
            if not raw:
                continue
            if raw.strip().startswith(("-", "*", "•")) or re.search(r"\d", raw):
                ing = normalize_ingredient_line(raw)
                if ing:
                    candidates.append(ing)

    # Deduplicate while preserving order, limit count
    seen = set()
    deduped: List[str] = []
    for ing in candidates:
        if ing not in seen:
            seen.add(ing)
            deduped.append(ing)
        if len(deduped) >= limit:
            break
    return deduped


def extract_text_from_pdf(file_bytes: bytes) -> str:
    if not HAS_PDF:
        raise RuntimeError("PDF parsing is not available on this server.")
    try:
        reader = PyPDF2.PdfReader(io.BytesIO(file_bytes))
        pages_text = []
        for page in reader.pages:
            try:
                pages_text.append(page.extract_text() or "")
            except Exception:
                continue
        return "\n".join(pages_text).strip()
    except Exception as e:
        raise RuntimeError(f"Failed to read PDF: {e}")

# --------- External Knowledge Lookups ---------

def http_get_json(url: str, params: Optional[dict] = None, timeout: float = HTTP_TIMEOUT) -> Optional[dict]:
    try:
        r = requests.get(url, params=params, headers=USER_AGENT, timeout=timeout)
        if r.status_code == 200:
            return r.json()
        else:
            logger.warning(f"GET {url} returned {r.status_code}")
            return None
    except requests.RequestException as e:
        logger.warning(f"GET {url} failed: {e}")
        return None


def truncate(text: str, max_len: int = 300) -> str:
    if not text:
        return ""
    text = re.sub(r"\s+", " ", text).strip()
    return (text[: max_len - 1] + "…") if len(text) > max_len else text


def wiki_summary(term: str) -> Optional[str]:
    # Try REST summary first
    safe_title = term.replace(" ", "_")
    url = f"https://en.wikipedia.org/api/rest_v1/page/summary/{requests.utils.quote(safe_title)}"
    try:
        r = requests.get(url, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            data = r.json()
            extract = data.get("extract") or ""
            if extract:
                return truncate(extract, 420)
    except requests.RequestException:
        pass

    # Action API search fallback
    search_api = "https://en.wikipedia.org/w/api.php"
    sdata = http_get_json(search_api, {
        "action": "opensearch",
        "search": term,
        "limit": 1,
        "namespace": 0,
        "format": "json",
        "redirects": "resolve",
    })
    if sdata and len(sdata) >= 4 and sdata[1]:
        title = sdata[1][0]
        edata = http_get_json(search_api, {
            "action": "query",
            "prop": "extracts",
            "exintro": 1,
            "explaintext": 1,
            "redirects": 1,
            "titles": title,
            "format": "json",
        })
        if edata:
            pages = edata.get("query", {}).get("pages", {})
            for _, p in pages.items():
                ext = p.get("extract")
                if ext:
                    return truncate(ext, 420)
    return None


def wikidata_description(term: str) -> Optional[str]:
    url = "https://www.wikidata.org/w/api.php"
    data = http_get_json(url, {
        "action": "wbsearchentities",
        "language": "en",
        "format": "json",
        "search": term,
        "limit": 1,
    })
    if data and data.get("search"):
        desc = data["search"][0].get("description")
        return truncate(desc, 160) if desc else None
    return None


def datamuse_adjectives(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"rel_jjb": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen:
                    continue
                if lw in {"good", "many", "more", "much", "little", "other"}:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


def datamuse_similar(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"ml": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen or " " in lw:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


LOOKUP_CACHE: Dict[str, Dict] = {}


def fetch_knowledge_for_ingredient(ing: str) -> Dict:
    if ing in LOOKUP_CACHE:
        return LOOKUP_CACHE[ing]

    summary = wiki_summary(ing) or ""
    desc = wikidata_description(ing) or ""
    adjs = datamuse_adjectives(ing, maxn=5)
    related = datamuse_similar(ing, maxn=5)

    data = {
        "ingredient": ing,
        "wikipedia_summary": summary,
        "wikidata_description": desc,
        "adjectives": adjs,
        "related": related,
        "sources": {
            "wikipedia": f"https://en.wikipedia.org/wiki/{requests.utils.quote(ing.replace(' ', '_'))}",
            "wikidata_search": f"https://www.wikidata.org/w/index.php?search={requests.utils.quote(ing)}",
            "datamuse": "https://api.datamuse.com/words"
        }
    }
    LOOKUP_CACHE[ing] = data
    return data

# --------- Spell Generator ---------

FALLBACK_ADJS = ["mystic", "luminous", "ancient", "whispering", "emberlit"]
FALLBACK_VERBS = ["stir", "summon", "invoke", "weave", "conjure"]
FALLBACK_ENDINGS = ["So mote it be.", "Thus the charm is sealed.", "Let the spell be done."]


def build_spell(ingredients: List[str], lore: Dict[str, Dict]) -> str:
    if not ingredients:
        return "Whisper into the empty cauldron; no ingredients, no incantation."

    # Collect evocative adjectives from lore
    adj_pool = []
    for ing in ingredients:
        adjs = lore.get(ing, {}).get("adjectives") or []
        adj_pool.extend(adjs)
    if not adj_pool:
        adj_pool = FALLBACK_ADJS[:]

    random.shuffle(adj_pool)
    epithets = ", ".join(adj_pool[:3]) if adj_pool else "mystic"

    lines = []
    # Opening
    lines.append(f"Hear me, {epithets} winds, as I bind this recipe's essence:")

    # Ingredient invocations
    for ing in ingredients:
        verbs = FALLBACK_VERBS[:]
        random.shuffle(verbs)
        v = verbs[0]
        desc = lore.get(ing, {}).get("wikidata_description") or lore.get(ing, {}).get("wikipedia_summary") or ""
        desc_short = truncate(desc, 120)
        if desc_short:
            lines.append(f"- {v.title()} the {ing} — {desc_short}.")
        else:
            lines.append(f"- {v.title()} the {ing} with intention.")

    # Closing couplet
    random.shuffle(FALLBACK_ENDINGS)
    lines.append("")
    lines.append(FALLBACK_ENDINGS[0])

    return "\n".join(lines)

# --------- HTML Rendering ---------

def render_page(title: str, body_html: str, status: int = 200):
    html_doc = f"""
