    return resp


def render_error(message: str, status: int = 400):
    body = f"""
    <h1>Something went wrong</h1>
    <div class=\"error\">{html.escape(message)}</div>
    <p><a href=\"/embed\">Go back</a> and try again.</p>
    """
    return render_page("Error", body, status)


# --------- Routes ---------

ALLOWED_EXT = {"txt", "pdf"}
MAX_TEXT_LEN = 40_000  # 40 KB of pasted text


def allowed_file(filename: str) -> bool:
    if not filename or "." not in filename:
        return False
    ext = filename.rsplit(".", 1)[1].lower()
    return ext in ALLOWED_EXT


@app.get("/embed")
def embed_get():
    body = f"""
    <h1>Recipe to Spell</h1>
    <p class=\"muted\">Paste your recipe or upload a .txt/.pdf file. We will extract ingredients and conjure a whimsical spell.</p>
    <form action=\"/embed\" method=\"post\" enctype=\"multipart/form-data\">
      <label for=\"recipe_text\"><strong>Pasted recipe (optional)</strong></label>
      <textarea id=\"recipe_text\" name=\"recipe_text\" maxlength=\"{MAX_TEXT_LEN}\" placeholder=\"Paste ingredients and/or full recipe here...\"></textarea>

      <label for=\"recipe_file\"><strong>Or upload a file (.txt or .pdf, up to 2 MB)</strong></label>
      <input id=\"recipe_file\" type=\"file\" name=\"recipe_file\" accept=\".txt,application/pdf\" />

      <button class=\"btn\" type=\"submit\">Conjure Spell</button>
    </form>
    <p class=\"muted\">By submitting, you agree that external lookups (Wikipedia, Wikidata, Datamuse) may be queried to inspire your spell.</p>
    """
    return render_page("Embed — Recipe to Spell", body)


@app.post("/embed")
def embed_post():
    # Validate input presence
    text = (request.form.get("recipe_text") or "").strip()
    file = request.files.get("recipe_file")

    if not text and (not file or file.filename.strip() == ""):
        return render_error("Please paste a recipe or upload a .txt/.pdf file.")

    # Validate pasted text length
    if text and len(text.encode("utf-8")) > MAX_TEXT_LEN:
        return render_error("Pasted text is too long. Please keep it under 40 KB.")

    extracted_text = ""

    # If file provided, validate and read
    if file and file.filename:
        if not allowed_file(file.filename):
            return render_error("Unsupported file type. Please upload a .txt or .pdf file.")

        # Enforce content length via Flask MAX_CONTENT_LENGTH; also double-check stream size when possible
        try:
            file_bytes = file.read()
        except Exception:
            return render_error("Could not read the uploaded file. Please try again.")

        if not file_bytes:
            return render_error("Uploaded file is empty.")
        if len(file_bytes) > app.config.get("MAX_CONTENT_LENGTH", 2 * 1024 * 1024):
            return render_error("File is too large. The limit is 2 MB.")

        ext = file.filename.rsplit(".", 1)[1].lower()
        if ext == "txt":
            try:
                extracted_text = file_bytes.decode("utf-8", errors="ignore")
            except Exception:
                return render_error("Could not decode the text file.")
        elif ext == "pdf":
            try:
                extracted_text = extract_text_from_pdf(file_bytes)
            except Exception as e:
                return render_error(str(e))
        else:
            return render_error("Unsupported file type. Please upload a .txt or .pdf file.")

    # Prefer pasted text if present; otherwise use extracted text from file
    recipe_text = text if text else extracted_text
    if not recipe_text.strip():
        return render_error("No recipe content found after processing. Please try again with a different file or paste text.")

    # Extract ingredients
    ingredients = extract_ingredients_from_text(recipe_text)
    if not ingredients:
        return render_error("We couldn't find any ingredients. Please ensure your recipe includes an Ingredients list or bullet points with quantities.")

    # Fetch knowledge for each ingredient (with basic resilience)
    lore: Dict[str, Dict] = {}
    for ing in ingredients:
        try:
            lore[ing] = fetch_knowledge_for_ingredient(ing)
        except Exception as e:
            logger.warning(f"Lookup failed for {ing}: {e}")
            lore[ing] = {"adjectives": [], "wikidata_description": "", "wikipedia_summary": ""}

    # Build spell
    spell_text = build_spell(ingredients, lore)

    # Render result page
    safe_spell = html.escape(spell_text)
    items_html = "".join(f"<li>{html.escape(ing)}</li>" for ing in ingredients)

    body = f"""
    <h1>Your Conjured Spell</h1>
    <div class=\"card\">
      <h2>Ingredients Detected</h2>
      <ul>{items_html}</ul>
    </div>
    <h2>Incantation</h2>
    <pre>{safe_spell}</pre>
    <p class=\"muted\">This spell was inspired by public sources like Wikipedia, Wikidata, and Datamuse.</p>
    <p><a href=\"/embed\">Conjure another</a></p>
    """
    return render_page("Your Spell", body)


@app.get("/")
def root():
    return redirect(url_for("embed_get"))


if __name__ == "__main__":
    port = int(os.environ.get("PORT", 5000))
    app.run(host="0.0.0.0", port=port, debug=False)
