    2) DPR-aware canvas setup (scene + labels)
    (Place in render/canvasRenderer.js; assumes two canvases: sceneCanvas and labelCanvas.)
    ```js
    // render/canvasRenderer.js
    import tinycolor from 'tinycolor2';
    import { worldToScreen, getView } from './scale.js';
    import { bodies } from '../data/bodies.js'; // array of { id, pos: [x,y], radius, color }

    const sceneCanvas = document.getElementById('sceneCanvas');
    const labelCanvas = document.getElementById('labelCanvas');
    const sceneCtx = sceneCanvas.getContext('2d');
    const labelCtx = labelCanvas.getContext('2d', { alpha: true });

    let lastDevicePixelRatio = 0;

    export function resizeIfNeeded() {
      const dpr = window.devicePixelRatio || 1;
      const cssW = sceneCanvas.clientWidth | 0;
      const cssH = sceneCanvas.clientHeight | 0;
      const targetW = Math.max(1, Math.floor(cssW * dpr));
      const targetH = Math.max(1, Math.floor(cssH * dpr));

      if (dpr !== lastDevicePixelRatio || sceneCanvas.width !== targetW || sceneCanvas.height !== targetH) {
        lastDevicePixelRatio = dpr;
        sceneCanvas.width = targetW;
        sceneCanvas.height = targetH;
        labelCanvas.width = targetW;
        labelCanvas.height = targetH;
        sceneCanvas.style.width = cssW + 'px';
        sceneCanvas.style.height = cssH + 'px';
        labelCanvas.style.width = cssW + 'px';
        labelCanvas.style.height = cssH + 'px';
        sceneCtx.setTransform(dpr, 0, 0, dpr, 0, 0); // scale drawing ops to CSS pixels
        labelCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }
    }

    export function renderFrame(alpha = 0) {
      const { view } = getView(); // returns { center:[x,y], zoom, w, h }

      // Clear
      sceneCtx.clearRect(0, 0, sceneCanvas.width, sceneCanvas.height);
      labelCtx.clearRect(0, 0, labelCanvas.width, labelCanvas.height);

      // Draw Sun glow
      const sunColor = tinycolor('#f5d76e');
      sceneCtx.save();
      sceneCtx.globalCompositeOperation = 'lighter';
      sceneCtx.fillStyle = sunColor.setAlpha(0.18).toRgbString();
      const sunScreen = worldToScreen([0, 0]);
      sceneCtx.beginPath();
      sceneCtx.arc(sunScreen[0], sunScreen[1], 40, 0, Math.PI * 2);
      sceneCtx.fill();
      sceneCtx.restore();

      // Bodies (very simplified point render; replace with orbits/paths)
      for (const b of bodies) {
        const p = worldToScreen(b.pos);
        sceneCtx.fillStyle = b.color;
        sceneCtx.beginPath();
        sceneCtx.arc(p[0], p[1], Math.max(1.5, b.radius), 0, Math.PI * 2);
        sceneCtx.fill();
      }
    }
