    3) Basic hit-testing and label collision with rbush
    (Place in render/labelManager.js; build label bboxes and query collisions.)
    ```js
    // render/labelManager.js
    import RBush from 'rbush';
    import { worldToScreen } from './scale.js';

    const tree = new RBush();

    export function layoutLabels(bodies, ctx) {
      tree.clear();
      const placed = [];

      for (const b of bodies) {
        const p = worldToScreen(b.pos);
        const text = b.name;
        ctx.font = '12px system-ui, sans-serif';
        const m = ctx.measureText(text);
        const w = Math.ceil(m.width + 6);
        const h = 14; // approx height

        // Try offsets around the point to reduce overlap
        const candidates = [
          { dx: 8, dy: -8 },
          { dx: 8, dy: 8 },
          { dx: -8 - w, dy: -8 },
          { dx: -8 - w, dy: 8 }
        ];

        let chosen = null;
        for (const c of candidates) {
          const x1 = p[0] + c.dx, y1 = p[1] + c.dy;
          const box = { minX: x1, minY: y1 - h, maxX: x1 + w, maxY: y1 };
          const hits = tree.search(box);
          if (hits.length === 0) { chosen = { box, pos: [x1, y1], text }; break; }
        }

        if (chosen) {
          tree.insert({ ...chosen.box, id: b.id });
          placed.push(chosen);
        }
      }

      return placed; // array of { box, pos:[x,y], text }
    }

    export function drawLabels(placed, ctx) {
      ctx.save();
      ctx.fillStyle = 'white';
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      for (const l of placed) {
        // halo
        ctx.lineWidth = 3;
        ctx.strokeText(l.text, l.pos[0], l.pos[1]);
        // text
        ctx.fillText(l.text, l.pos[0], l.pos[1]);
      }
      ctx.restore();
    }
